window.ATLAS_BUNDLES=window.ATLAS_BUNDLES||{};window.ATLAS_BUNDLES["annotations-019"]={"HECTD1":{"hgnc":"HGNC:20157","symbol":"HECTD1","accessions":["Q9ULT8"],"name":"E3 ubiquitin-protein ligase HECTD1","length":"2610","function":"E3 ubiquitin-protein ligase which accepts ubiquitin from an E2 ubiquitin-conjugating enzyme in the form of a thioester and then directly transfers the ubiquitin to targeted substrates (PubMed:33711283). Mediates 'Lys-63'-linked polyubiquitination of HSP90AA1 which leads to its intracellular localization and reduced secretion (By similarity). Negatively regulating HSP90AA1 secretion in cranial mesenchyme cells may impair their emigration and may be essential for the correct development of the cranial neural folds and neural tube closure (By similarity). Catalyzes ubiquitination and degradation of ZNF622, an assembly factor for the ribosomal 60S subunit, in hematopoietic cells, thereby promoting hematopoietic stem cell renewal (PubMed:33711283)","subunit":"Interacts with IGSF1 (PubMed:12421765)","family":"Belongs to the UPL family. K-HECT subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["33711283"],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；翻译/核糖体；发育/分化；注释原文：E3 ubiquitin-protein ligase which accepts ubiquitin from an E2 ubiquitin-conjugating enzyme in the form of a thioester and then directly transfers the ubiquitin to targeted substrates (PubMed:33711283).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；翻译/核糖体；发育/分化"},"HECW1":{"hgnc":"HGNC:22195","symbol":"HECW1","accessions":["Q76N89"],"name":"E3 ubiquitin-protein ligase HECW1","length":"1606","function":"E3 ubiquitin-protein ligase that mediates ubiquitination and subsequent degradation of DVL1. Also targets the mutant SOD1 protein involved in familial amyotrophic lateral sclerosis (FALS). Forms cytotoxic aggregates with DVL1, SSR3 and mutant SOD1 that lead to motor neuron death in FALS","subunit":"Interacts with DVL1 and SSR3. Also interacts with mutant SOD1","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["14684739"],"location":"Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；注释原文：E3 ubiquitin-protein ligase that mediates ubiquitination and subsequent degradation of DVL1.","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态"},"HELLS":{"hgnc":"HGNC:4861","symbol":"HELLS","accessions":["Q9NRZ9"],"name":"Lymphoid-specific helicase","length":"838","function":"ATP-dependent chromatin remodeler that regulates chromatin accessibility, DNA methylation, and histone modifications. It facilitates de novo DNA methylation at repetitive sequences and promotes transcriptional silencing via recruitment of DNA methyltransferases (DNMTs) and histone deacetylases (HDACs), contributing to heterochromatin formation and repression of transposable elements (PubMed:30307408). Also involved in DNA repair by recruiting DNA damage response mediators to double-strand breaks in heterochromatin, promoting homologous recombination via RBBP8/CtIP-dependent end resection (PubMed:22946062, PubMed:31802118). During meiosis, it is recruited by PRDM9 to recombination hotspots, aiding chromatin opening (PubMed:32001511). Through these diverse roles, is crucial for processes such as development, differentiation, and genomic stability (PubMed:22946062, PubMed:31802118). Involved in regulation of the expansion or survival of lymphoid cells (By similarity)","subunit":"Interacts with RBBP8/CtIP; the interaction leads to recruitment of RBBP8/CtIP to sites of DNA breaks (PubMed:31802118). Interacts with PRDM9; the interaction recruits HELLS to meiotic recombination hot spots (PubMed:32001511). Interacts with CDCA7; the interaction brings HELLS to chromatin and recruits DNA methyltransferases to heterochromatin regions (PubMed:30307408)","family":"Belongs to the SNF2/RAD54 helicase family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["22946062","30307408","31802118","32001511"],"location":"Nucleus；Chromosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；DNA修复/复制；发育/分化；注释原文：ATP-dependent chromatin remodeler that regulates chromatin accessibility, DNA methylation, and histone modifications.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；DNA修复/复制；发育/分化"},"HELZ":{"hgnc":"HGNC:16878","symbol":"HELZ","accessions":["P42694"],"name":"ATP-dependent RNA helicase with zinc finger domain","length":"1942","function":"ATP-dependent RNA helicase that promotes degradation of mRNAs via its association with the CCR4-NOT deadenylase complex, leading to deadenylation, decapping, and subsequent degradation of target mRNAs (PubMed:31570513). Can repress translation independently of mRNA decay in a manner dependent on both the CCR4-NOT complex and the helicase DDX6 (PubMed:31570513). Involved in promoting cell proliferation, translation initiation, and ribosomal protein S6 (RPS6) phosphorylation (PubMed:21765940)","subunit":"Interacts with SMYD2 (By similarity). Interacts with POLR2A (PubMed:15235609). Interacts with SMYD3; the interaction may bridge SMYD3 and RNA polymerase II (PubMed:15235609). Interacts with PAN3, EDC4, PATL1 and with CCR4-NOT complex components CNOT1 and CNOT3 (PubMed:31570513). Interacts (via the PAM2 motif) with PABPC1 (PubMed:21765940, PubMed:31570513)","family":"Belongs to the DNA2/NAM7 helicase family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["21765940","31570513"],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；翻译/核糖体；注释原文：ATP-dependent RNA helicase that promotes degradation of mRNAs via its association with the CCR4-NOT deadenylase complex, leading to deadenylation, decapping, and subsequent degradation of target mRNAs (PubMed:31570513).","function_evidence":"含实验支持条目；ECO:0000269","categories":"激酶/磷酸化信号；翻译/核糖体"},"HENMT1":{"hgnc":"HGNC:26400","symbol":"HENMT1","accessions":["Q5T8I9"],"name":"Small RNA 2'-O-methyltransferase","length":"393","function":"Methyltransferase that adds a 2'-O-methyl group at the 3'-end of piRNAs, a class of 24 to 30 nucleotide RNAs that are generated by a Dicer-independent mechanism and are primarily derived from transposons and other repeated sequence elements. This probably protects the 3'-end of piRNAs from uridylation activity and subsequent degradation. Stabilization of piRNAs is essential for gametogenesis","subunit":"","family":"Belongs to the methyltransferase superfamily. HEN1 family","domains":[],"function_pmids":[],"location":"Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Methyltransferase that adds a 2'-O-methyl group at the 3'-end of piRNAs, a class of 24 to 30 nucleotide RNAs that are generated by a Dicer-independent mechanism and are primarily derived from transposons and other repeated sequence elements. This probably protects the 3'-end of piRNAs from uridylation activity and subsequent degradation. Stabilization of piRNAs is essential for gametogenesis"},"HERC2":{"hgnc":"HGNC:4868","symbol":"HERC2","accessions":["O95714"],"name":"E3 ubiquitin-protein ligase HERC2","length":"4834","function":"E3 ubiquitin-protein ligase that regulates ubiquitin-dependent retention of repair proteins on damaged chromosomes. Recruited to sites of DNA damage in response to ionizing radiation (IR) and facilitates the assembly of UBE2N and RNF8 promoting DNA damage-induced formation of 'Lys-63'-linked ubiquitin chains. Acts as a mediator of binding specificity between UBE2N and RNF8. Involved in the maintenance of RNF168 levels. E3 ubiquitin-protein ligase that promotes the ubiquitination and proteasomal degradation of XPA which influences the circadian oscillation of DNA excision repair activity. By controlling the steady-state expression of the IGF1R receptor, indirectly regulates the insulin-like growth factor receptor signaling pathway (PubMed:26692333). Also modulates iron metabolism by regulating the basal turnover of FBXL5 (PubMed:24778179)","subunit":"Interacts (when phosphorylated at Thr-4827 and sumoylated) with RNF8 (via FHA domain); this interaction increases after ionizing radiation (IR) treatment. Interacts with XPA. Interacts with NEURL4. Via its interaction with NEURL4, may indirectly interact with CCP110 and CEP97","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["20023648","20304803","22508508","24778179","26692333"],"location":"Cytoplasm；Cytoplasm, cytoskeleton, microtubule organizing center, centrosome, centriole；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；DNA修复/复制；线粒体/代谢；黏附/受体/细胞表面；注释原文：E3 ubiquitin-protein ligase that regulates ubiquitin-dependent retention of repair proteins on damaged chromosomes.","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；DNA修复/复制；线粒体/代谢；黏附/受体/细胞表面"},"HERC4":{"hgnc":"HGNC:24521","symbol":"HERC4","accessions":["Q5GLZ8"],"name":"Probable E3 ubiquitin-protein ligase HERC4","length":"1057","function":"Probable E3 ubiquitin-protein ligase involved in either protein trafficking or in the distribution of cellular structures. Required for spermatozoon maturation and fertility, and for the removal of the cytoplasmic droplet of the spermatozoon. E3 ubiquitin-protein ligases accept ubiquitin from an E2 ubiquitin-conjugating enzyme in the form of a thioester and then directly transfer it to targeted substrates","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Cytoplasm, cytosol","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；发育/分化；注释原文：Probable E3 ubiquitin-protein ligase involved in either protein trafficking or in the distribution of cellular structures.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"泛素化/蛋白稳态；发育/分化"},"HERPUD2":{"hgnc":"HGNC:21915","symbol":"HERPUD2","accessions":["Q9BSE4"],"name":"Homocysteine-responsive endoplasmic reticulum-resident ubiquitin-like domain member 2 protein","length":"406","function":"Could be involved in the unfolded protein response (UPR) pathway","subunit":"","family":"","domains":[],"function_pmids":[],"location":"Membrane","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Could be involved in the unfolded protein response (UPR) pathway"},"HES6":{"hgnc":"HGNC:18254","symbol":"HES6","accessions":["Q96HZ4"],"name":"Transcription cofactor HES-6","length":"224","function":"Does not bind DNA itself but suppresses both HES1-mediated N box-dependent transcriptional repression and binding of HES1 to E box sequences. Also suppresses HES1-mediated inhibition of the heterodimer formed by ASCL1/MASH1 and TCF3/E47, allowing ASCL1 and TCF3 to up-regulate transcription in its presence. Promotes cell differentiation (By similarity)","subunit":"Transcription repression requires formation of a complex with a corepressor protein of the Groucho/TLE family. Interacts with HES1 (By similarity)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；发育/分化；注释原文：Does not bind DNA itself but suppresses both HES1-mediated N box-dependent transcriptional repression and binding of HES1 to E box sequences.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"染色质/转录调控；发育/分化"},"HES7":{"hgnc":"HGNC:15977","symbol":"HES7","accessions":["Q9BYE0"],"name":"Transcription factor HES-7","length":"225","function":"Transcriptional repressor. Represses transcription from both N box- and E box-containing promoters. May with HES1, cooperatively regulate somite formation in the presomitic mesoderm (PSM). May function as a segmentation clock, which is essential for coordinated somite segmentation (By similarity)","subunit":"Transcription repression requires formation of a complex with a corepressor protein of the Groucho/TLE family","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；注释原文：Transcriptional repressor.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"染色质/转录调控"},"HEXD":{"hgnc":"HGNC:26307","symbol":"HEXD","accessions":["Q8WVB3"],"name":"Hexosaminidase D","length":"486","function":"Has hexosaminidase activity. Responsible for the cleavage of the monosaccharides N-acetylglucosamine (GlcNAc) and N-acetylgalactosamine (GalNAc) from cellular substrates. Has a preference for galactosaminide over glucosaminide substrates (PubMed:27149221)","subunit":"Homodimer; disulfide-linked","family":"Belongs to the glycosyl hydrolase 20 family","domains":[],"function_pmids":["19040401","23099419","27149221"],"location":"Cytoplasm; Nucleus; Extracellular vesicle","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Has hexosaminidase activity. Responsible for the cleavage of the monosaccharides N-acetylglucosamine (GlcNAc) and N-acetylgalactosamine (GalNAc) from cellular substrates. Has a preference for galactosaminide over glucosaminide substrates (PubMed:27149221)"},"HEXIM1":{"hgnc":"HGNC:24953","symbol":"HEXIM1","accessions":["O94992"],"name":"Protein HEXIM1","length":"359","function":"Transcriptional regulator which functions as a general RNA polymerase II transcription inhibitor (PubMed:14580347, PubMed:15201869, PubMed:15713661). Core component of the 7SK RNP complex: in cooperation with 7SK snRNA sequesters P-TEFb in a large inactive 7SK snRNP complex preventing RNA polymerase II phosphorylation and subsequent transcriptional elongation (PubMed:12832472, PubMed:14580347, PubMed:15201869, PubMed:15713661). May also regulate NF-kappa-B, ESR1, NR3C1 and CIITA-dependent transcriptional activity (PubMed:15940264, PubMed:15941832, PubMed:17088550). Plays a role in the regulation of DNA virus-mediated innate immune response by assembling into the HDP-RNP complex, a complex that serves as a platform for IRF3 phosphorylation and subsequent innate immune response activation through the cGAS-STING pathway (PubMed:28712728)","subunit":"Homooligomer and heterooligomer with HEXIM2; probably dimeric (PubMed:15713661, PubMed:15965233, PubMed:16377779). Core component of the 7SK RNP complex, at least composed of 7SK RNA, LARP7, MEPCE, HEXIM1 (or HEXIM2) and P-TEFb (composed of CDK9 and CCNT1/cyclin-T1) (PubMed:12832472, PubMed:15169877, PubMed:15201869, PubMed:15713661, PubMed:15855166, PubMed:16362050, PubMed:16377779, PubMed:17643375, PubMed:17724342, PubMed:30134174). Interacts with the N-CoR complex through NCOR1 (PubMed:17452463). Interacts with ESR1 and NR3C1 (PubMed:15940264, PubMed:15941832). May interact with NF-kappa-B through RELA (PubMed:12581153). Interacts with CCNT2; mediates formation of a tripartite complex with KPNA2 (PubMed:19883659). Part of the HDP-RNP complex composed of at least HEXIM1, PRKDC, XRCC5, XRCC6, paraspeckle proteins (SFPQ, NONO, PSPC1, RBM14, and MATR3) and NEAT1 non-coding RNA (PubMed:28712728)","family":"Belongs to the HEXIM family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12581153","12832472","14580347","15201869","15713661","15940264","15941832","17088550","28712728"],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；激酶/磷酸化信号；免疫/炎症/细胞死亡；注释原文：Transcriptional regulator which functions as a general RNA polymerase II transcription inhibitor (PubMed:14580347, PubMed:15201869, PubMed:15713661).","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控；激酶/磷酸化信号；免疫/炎症/细胞死亡"},"HEY1":{"hgnc":"HGNC:4880","symbol":"HEY1","accessions":["Q9Y5J3"],"name":"Hairy/enhancer-of-split related with YRPW motif protein 1","length":"304","function":"Transcriptional repressor which binds preferentially to the canonical E box sequence 5'-CACGTG-3' (PubMed:11095750). Downstream effector of Notch signaling required for cardiovascular development. Specifically required for the Notch-induced endocardial epithelial to mesenchymal transition, which is itself criticial for cardiac valve and septum development. May be required in conjunction with HEY2 to specify arterial cell fate or identity. Promotes maintenance of neuronal precursor cells and glial versus neuronal fate specification. Represses transcription by the cardiac transcriptional activators GATA4 and GATA6 and by the neuronal bHLH factors ASCL1/MASH1 and NEUROD4/MATH3 (PubMed:15485867). Involved in the regulation of liver cancer cells self-renewal (PubMed:25985737)","subunit":"Self-associates. Interacts with HES1 and HEYL. Interacts with HDAC1, NCOR1 and SIN3A. Interacts with GATA4 and GATA6. Interacts with CCDC89/BOIP","family":"Belongs to the HEY family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11095750","15485867","25985737"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；发育/分化；注释原文：Transcriptional repressor which binds preferentially to the canonical E box sequence 5'-CACGTG-3' (PubMed:11095750).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；发育/分化"},"HIC2":{"hgnc":"HGNC:18595","symbol":"HIC2","accessions":["Q96JB3"],"name":"Hypermethylated in cancer 2 protein","length":"615","function":"Transcriptional repressor","subunit":"Self-associates. Interacts with HIC1","family":"Belongs to the krueppel C2H2-type zinc-finger protein family. Hic subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；注释原文：Transcriptional repressor","function_evidence":"数据库整理/推断；按原文限定；","categories":"染色质/转录调控"},"HIF1A":{"hgnc":"HGNC:4910","symbol":"HIF1A","accessions":["Q16665"],"name":"Hypoxia-inducible factor 1-alpha","length":"826","function":"Functions as a master transcriptional regulator of the adaptive response to hypoxia (PubMed:11292861, PubMed:11566883, PubMed:15465032, PubMed:16973622, PubMed:17610843, PubMed:18658046, PubMed:20624928, PubMed:22009797, PubMed:30125331, PubMed:9887100). Under hypoxic conditions, activates the transcription of over 40 genes, including erythropoietin, glucose transporters, glycolytic enzymes, vascular endothelial growth factor, HILPDA, and other genes whose protein products increase oxygen delivery or facilitate metabolic adaptation to hypoxia (PubMed:11292861, PubMed:11566883, PubMed:15465032, PubMed:16973622, PubMed:17610843, PubMed:20624928, PubMed:22009797, PubMed:30125331, PubMed:9887100). Plays an essential role in embryonic vascularization, tumor angiogenesis and pathophysiology of ischemic disease (PubMed:22009797). Heterodimerizes with ARNT; heterodimer binds to core DNA sequence 5'-TACGTG-3' within the hypoxia response element (HRE) of target gene promoters (By similarity). Activation requires recruitment of transcriptional coactivators such as CREBBP and EP300 (PubMed:16543236, PubMed:9887100). Activity is enhanced by interaction with NCOA1 and/or NCOA2 (PubMed:10594042). Interaction with redox regulatory protein APEX1 seems to activate CTAD and potentiates activation by NCOA1 and CREBBP (PubMed:10202154, PubMed:10594042). Involved in the axonal distribution and transport of mitochondria in neurons during hypoxia (PubMed:19528298)\n(Microbial infection) Upon infection by human coronavirus SARS-CoV-2, is required for induction of glycolysis in monocytes and the consequent pro-inflammatory state (PubMed:32697943). In monocytes, induces expression of ACE2 and cytokines such as IL1B, TNF, IL6, and interferons (PubMed:32697943). Promotes human coronavirus SARS-CoV-2 replication and monocyte inflammatory response (PubMed:32697943)","subunit":"Interacts with the ARNT; forms a heterodimer that binds core DNA sequence 5'-TACGTG-3' within the hypoxia response element (HRE) of target gene promoters (PubMed:10944113, PubMed:20699359). Interacts with COPS5; the interaction increases the transcriptional activity of HIF1A through increased stability (By similarity). Interacts with EP300 (via TAZ-type 1 domains); the interaction is stimulated in response to hypoxia and inhibited by CITED2 (PubMed:11959990, PubMed:12778114, PubMed:16543236, PubMed:16973622, PubMed:8917528, PubMed:9887100). Interacts with CREBBP (via TAZ-type 1 domains) (PubMed:11959977, PubMed:8917528). Interacts with NCOA1, NCOA2, APEX1 and HSP90 (PubMed:10202154, PubMed:10594042). Interacts (hydroxylated within the ODD domain) with VHLL (via beta domain); the interaction, leads to polyubiquitination and subsequent HIF1A proteasomal degradation (PubMed:14757845). During hypoxia, sumoylated HIF1A also binds VHL; the interaction promotes the ubiquitination of HIF1A (PubMed:10944113, PubMed:11006129, PubMed:12004076, PubMed:12050673, PubMed:16862177). Interacts with SENP1; the interaction desumoylates HIF1A resulting in stabilization and activation of transcription (By similarity). Interacts (via the ODD domain) with NAA10; the interaction appears not to acetylate HIF1A nor have any affect on protein stability, during hypoxia (PubMed:12464182, PubMed:16288748). Interacts with RWDD3; the interaction enhances HIF1A sumoylation (PubMed:17956732, PubMed:23469069). Interacts with TSGA10 (By similarity). Interacts with HIF3A (By similarity). Interacts with RORA (via the DNA binding domain); the interaction enhances HIF1A transcription under hypoxia through increasing protein stability (PubMed:18658046). Interaction with PSMA7 inhibits the transactivation activity of HIF1A under both normoxic and hypoxia-mimicking conditions (PubMed:11389899). Interacts with USP20 (PubMed:15776016). Interacts with RACK1; promotes HIF1A ubiquitination and proteasome-mediated degradation (PubMed:17244529). Interacts (via N-terminus) with USP19 (PubMed:22128162). Interacts with SIRT2 (PubMed:24681946). Interacts (deacetylated form) with EGLN1 (PubMed:24681946). Interacts with CBFA2T3 (PubMed:25974097). Interacts with HSP90AA1 and HSP90AB1 (PubMed:26517842). Interacts with DCUN1D1; this interaction increases the interaction between VHL and DCUN1D1 (PubMed:23401859). Interacts with HIF1AN (PubMed:12446723)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10202154","10594042","11292861","11566883","15465032","16543236","16973622","17610843","18658046","19528298","20624928","22009797","30125331","32697943","9887100"],"location":"Cytoplasm；Nucleus；Nucleus speckle","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；免疫/炎症/细胞死亡；线粒体/代谢；注释原文：Functions as a master transcriptional regulator of the adaptive response to hypoxia (PubMed:11292861, PubMed:11566883, PubMed:15465032, PubMed:16973622, PubMed:17610843, PubMed:18658046, PubMed:20624928, PubMed:22009797, PubMed:30125331, PubMed:9887100).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；免疫/炎症/细胞死亡；线粒体/代谢"},"HIF1AN":{"hgnc":"HGNC:17113","symbol":"HIF1AN","accessions":["Q9NWT6"],"name":"Hypoxia-inducible factor 1-alpha inhibitor","length":"349","function":"Hydroxylates HIF-1 alpha at 'Asn-803' in the C-terminal transactivation domain (CAD). Functions as an oxygen sensor and, under normoxic conditions, the hydroxylation prevents interaction of HIF-1 with transcriptional coactivators including Cbp/p300-interacting transactivator. Involved in transcriptional repression through interaction with HIF1A, VHL and histone deacetylases. Hydroxylates specific Asn residues within ankyrin repeat domains (ARD) of NFKB1, NFKBIA, NOTCH1, ASB4, PPP1R12A and several other ARD-containing proteins. Also hydroxylates Asp and His residues within ARDs of ANK1 and TNKS2, respectively. Negatively regulates NOTCH1 activity, accelerating myogenic differentiation. Positively regulates ASB4 activity, promoting vascular differentiation","subunit":"Homodimer; homodimerization is essential for catalytic activity. Interacts with VHL and HIF1A. Part of a complex with VHL, HIF1A and HDAC1 or HDAC2 or HDAC3. Interacts with NFKB1 and NFKBIA. Interacts with NOTCH1, NOTCH2 and NOTCH3 but not with NOTCH4. Interacts with APBA3; binding inhibits HIF1AN binding to HIF1A. Interacts with TNKS2. Interacts with PPP1R12A. Interacts with ASB4 (By similarity). Interacts with UBE3A. Interacts with ANKS3 (By similarity). Interacts with NECAB3; the interaction is indirect and seems to be mediated by APBA3","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12042299","12080085","17003112","17573339","18299578","19245366","21177872","21251231"],"location":"Nucleus；Cytoplasm；Cytoplasm, perinuclear region","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"FIH1；2OG依赖天冬酰胺羟化酶，调节HIF转录活性。","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控；发育/分化"},"HIKESHI":{"hgnc":"HGNC:26938","symbol":"HIKESHI","accessions":["Q53FT3"],"name":"Protein Hikeshi","length":"197","function":"Acts as a specific nuclear import carrier for HSP70 proteins following heat-shock stress: acts by mediating the nucleoporin-dependent translocation of ATP-bound HSP70 proteins into the nucleus. HSP70 proteins import is required to protect cells from heat shock damages. Does not translocate ADP-bound HSP70 proteins into the nucleus","subunit":"Forms an asymmetric homodimer; required for binding and nuclear import of HSP70 proteins (PubMed:25760597). Interacts with ATP-bound HSP70 proteins (PubMed:22541429). Interacts with NUP62 and NUP153 (via F-X-F-G repeats) (PubMed:22541429). Interacts with HSPA8 (PubMed:25760597)","family":"Belongs to the OPI10 family","domains":[],"function_pmids":["22541429"],"location":"Cytoplasm; Cytoplasm, cytosol; Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Acts as a specific nuclear import carrier for HSP70 proteins following heat-shock stress: acts by mediating the nucleoporin-dependent translocation of ATP-bound HSP70 proteins into the nucleus. HSP70 proteins import is required to protect cells from heat shock damages. Does not translocate ADP-bound HSP70 proteins into the nucleus"},"HIP1":{"hgnc":"HGNC:4913","symbol":"HIP1","accessions":["O00291"],"name":"Huntingtin-interacting protein 1","length":"1037","function":"Plays a role in clathrin-mediated endocytosis and trafficking (PubMed:11532990, PubMed:11577110, PubMed:11889126). Involved in regulating AMPA receptor trafficking in the central nervous system in an NMDA-dependent manner (By similarity). Regulates presynaptic nerve terminal activity (By similarity). Enhances androgen receptor (AR)-mediated transcription (PubMed:16027218). May act as a proapoptotic protein that induces cell death by acting through the intrinsic apoptosis pathway (PubMed:11007801). Binds 3-phosphoinositides (via ENTH domain) (PubMed:14732715). May act through the ENTH domain to promote cell survival by stabilizing receptor tyrosine kinases following ligand-induced endocytosis (PubMed:14732715). May play a functional role in the cell filament networks (PubMed:18790740). May be required for differentiation, proliferation, and/or survival of somatic and germline progenitors (PubMed:11007801, PubMed:12163454)","subunit":"Homodimer. Binds actin. Binds HTT (via N-terminus). This interaction is restricted to the brain. Binds to IFT57. In normal conditions, it poorly interacts with IFT57, HIP1 being strongly associated with HTT. However, in mutant HTT proteins with a long poly-Gln region, interaction between HTT and HIP1 is inhibited, promoting the interaction between HIP1 and IFT57. Interacts with CLTB (via N-terminus). Interacts (via coiled coil domain) with AR. Interacts with AP2A1, AP2A2, CLTC and HIP1R. Interacts with GRIA1, GRIN2A and GRIN2B","family":"Belongs to the SLA2 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11007801","11532990","11577110","11889126","12163454","14732715","16027218","18790740","9147654"],"location":"Cytoplasm；Nucleus；Endomembrane system；Cytoplasmic vesicle, clathrin-coated vesicle membrane","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；激酶/磷酸化信号；膜运输/高尔基/内吞；免疫/炎症/细胞死亡；黏附/受体/细胞表面；发育/分化；注释原文：Plays a role in clathrin-mediated endocytosis and trafficking (PubMed:11532990, PubMed:11577110, PubMed:11889126).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；激酶/磷酸化信号；膜运输/高尔基/内吞；免疫/炎症/细胞死亡；黏附/受体/细胞表面；发育/分化"},"HIVEP1":{"hgnc":"HGNC:4920","symbol":"HIVEP1","accessions":["P15822"],"name":"Zinc finger protein 40","length":"2718","function":"This protein specifically binds to the DNA sequence 5'-GGGACTTTCC-3' which is found in the enhancer elements of numerous viral promoters such as those of SV40, CMV, or HIV-1. In addition, related sequences are found in the enhancer elements of a number of cellular promoters, including those of the class I MHC, interleukin-2 receptor, and interferon-beta genes. It may act in T-cell activation. Involved in activating HIV-1 gene expression. Isoform 2 and isoform 3 also bind to the IPCS (IRF1 and p53 common sequence) DNA sequence in the promoter region of interferon regulatory factor 1 and p53 genes and are involved in transcription regulation of these genes. Isoform 2 does not activate HIV-1 gene expression. Isoform 2 and isoform 3 may be involved in apoptosis","subunit":"Interacts with UTP4","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；免疫/炎症/细胞死亡；黏附/受体/细胞表面；注释原文：This protein specifically binds to the DNA sequence 5'-GGGACTTTCC-3' which is found in the enhancer elements of numerous viral promoters such as those of SV40, CMV, or HIV-1.","function_evidence":"数据库整理/推断；按原文限定；","categories":"染色质/转录调控；免疫/炎症/细胞死亡；黏附/受体/细胞表面"},"HIVEP2":{"hgnc":"HGNC:4921","symbol":"HIVEP2","accessions":["P31629"],"name":"Transcription factor HIVEP2","length":"2446","function":"This protein specifically binds to the DNA sequence 5'-GGGACTTTCC-3' which is found in the enhancer elements of numerous viral promoters such as those of SV40, CMV, or HIV1. In addition, related sequences are found in the enhancer elements of a number of cellular promoters, including those of the class I MHC, interleukin-2 receptor, somatostatin receptor II, and interferon-beta genes. It may act in T-cell activation","subunit":"Interacts with TCF4","family":"","domains":[],"function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"This protein specifically binds to the DNA sequence 5'-GGGACTTTCC-3' which is found in the enhancer elements of numerous viral promoters such as those of SV40, CMV, or HIV1. In addition, related sequences are found in the enhancer elements of a number of cellular promoters, including those of the class I MHC, interleukin-2 receptor, somatostatin receptor II, and interferon-beta genes. It may act in T-cell activation"},"HLA-DPB1":{"hgnc":"HGNC:4940","symbol":"HLA-DPB1","accessions":["P04440"],"name":"HLA class II histocompatibility antigen, DP beta 1 chain","length":"258","function":"Binds peptides derived from antigens that access the endocytic route of antigen presenting cells (APC) and presents them on the cell surface for recognition by the CD4 T-cells. The peptide binding cleft accommodates peptides of 10-30 residues. The peptides presented by MHC class II molecules are generated mostly by degradation of proteins that access the endocytic route, where they are processed by lysosomal proteases and other hydrolases. Exogenous antigens that have been endocytosed by the APC are thus readily available for presentation via MHC II molecules, and for this reason this antigen presentation pathway is usually referred to as exogenous. As membrane proteins on their way to degradation in lysosomes as part of their normal turn-over are also contained in the endosomal/lysosomal compartments, exogenous antigens must compete with those derived from endogenous components. Autophagy is also a source of endogenous peptides, autophagosomes constitutively fuse with MHC class II loading compartments. In addition to APCs, other cells of the gastrointestinal tract, such as epithelial cells, express MHC class II molecules and CD74 and act as APCs, which is an unusual trait of the GI tract. To produce a MHC class II molecule that presents an antigen, three MHC class II molecules (heterodimers of an alpha and a beta chain) associate with a CD74 trimer in the ER to form a heterononamer. Soon after the entry of this complex into the endosomal/lysosomal system where antigen processing occurs, CD74 undergoes a sequential degradation by various proteases, including CTSS and CTSL, leaving a small fragment termed CLIP (class-II-associated invariant chain peptide). The removal of CLIP is facilitated by HLA-DM via direct binding to the alpha-beta-CLIP complex so that CLIP is released. HLA-DM stabilizes MHC class II molecules until primary high affinity antigenic peptides are bound. The MHC II molecule bound to a peptide is then transported to the cell membrane surface. In B-cells, the interaction between HLA-DM and MHC class II molecules is regulated by HLA-DO. Primary dendritic cells (DCs) also to express HLA-DO. Lysosomal microenvironment has been implicated in the regulation of antigen loading into MHC II molecules, increased acidification produces increased proteolysis and efficient peptide loading","subunit":"Heterodimer of an alpha and a beta subunit; also referred as MHC class II molecule. In the endoplasmic reticulum (ER) it forms a heterononamer; 3 MHC class II molecules bind to a CD74 homotrimer (also known as invariant chain or HLA class II histocompatibility antigen gamma chain). In the endosomal/lysosomal system; CD74 undergoes sequential degradation by various proteases; leaving a small fragment termed CLIP on each MHC class II molecule. MHC class II molecule interacts with HLA_DM, and HLA_DO in B-cells, in order to release CLIP and facilitate the binding of antigenic peptides","family":"Belongs to the MHC class II family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Cell membrane；Single-pass type I membrane protein；Endoplasmic reticulum membrane；Golgi apparatus, trans-Golgi network membrane；Endosome membrane；Lysosome membrane","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"膜运输/高尔基/内吞；线粒体/代谢；注释原文：Binds peptides derived from antigens that access the endocytic route of antigen presenting cells (APC) and presents them on the cell surface for recognition by the CD4 T-cells.","function_evidence":"数据库整理/推断；按原文限定；","categories":"膜运输/高尔基/内吞；线粒体/代谢"},"HLCS":{"hgnc":"HGNC:4976","symbol":"HLCS","accessions":["P50747"],"name":"Biotin--protein ligase","length":"726","function":"Biotin--protein ligase catalyzing the biotinylation of the 4 biotin-dependent carboxylases acetyl-CoA-carboxylase, pyruvate carboxylase, propionyl-CoA carboxylase, and methylcrotonyl-CoA carboxylase","subunit":"Monomer","family":"Belongs to the biotin--protein ligase family","domains":[],"function_pmids":["10590022","7753853","7842009"],"location":"Cytoplasm; Mitochondrion","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Biotin--protein ligase catalyzing the biotinylation of the 4 biotin-dependent carboxylases acetyl-CoA-carboxylase, pyruvate carboxylase, propionyl-CoA carboxylase, and methylcrotonyl-CoA carboxylase"},"HLF":{"hgnc":"HGNC:4977","symbol":"HLF","accessions":["Q16534"],"name":"Transcription factor HLF","length":"295","function":"Transcription factor which selectively binds with high affinity to the consensus sequence 5'-GTTACGTAAT-3' and to closely related sites (PubMed:8065331, PubMed:8164688, PubMed:8639829). Has transcriptional activator activity (PubMed:10073576, PubMed:8065331, PubMed:8164688, PubMed:8639829). Also has transcriptional repressor activity (By similarity). Binds to multiple sites in the promoter regions of coagulation factors F8 and F9 and activates transcription; transactivation activity is enhanced by formation of a heterodimer with DBP (PubMed:10073576). Binds to the promoter region of IRF2 and activates transcription (By similarity). Maintains quiescence of hematopoietic stem cells under steady-state conditions and protects the stem cell pool from toxic insults (By similarity). Regulates the tissue residency and proinflammatory function of CD4+ tissue-resident memory T (TRM) cells (By similarity). Down-regulates the expression of genes involved in promoting tissue egress of CD4+ TRM cells including S1PR1, KLF2 and TCF7 while up-regulating expression of tissue retention molecules such as CD69 (By similarity). Also up-regulates BHLHE40 expression, promoting proinflammatory cytokine production (By similarity)","subunit":"Binds DNA specifically as a homodimer or a heterodimer with other PAR factors (PubMed:1516826). Forms heterodimers with PAR protein DBP; this enhances transactivation activity towards coagulation factors F8 and F9 (PubMed:10073576)","family":"Belongs to the bZIP family. PAR subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10073576","8065331","8164688","8639829"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；免疫/炎症/细胞死亡；注释原文：Transcription factor which selectively binds with high affinity to the consensus sequence 5'-GTTACGTAAT-3' and to closely related sites (PubMed:8065331, PubMed:8164688, PubMed:8639829).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；免疫/炎症/细胞死亡"},"HLTF":{"hgnc":"HGNC:11099","symbol":"HLTF","accessions":["Q14527"],"name":"DNA-dependent ATPase/E3 ubiquitin-protein ligase HLTF","length":"1009","function":"Functions as a DNA-dependent ATPase and E3 ubiquitin-protein ligase involved in chromatin regulation and DNA damage tolerance (DDT) (PubMed:18316726, PubMed:18719106, PubMed:26051180, PubMed:31960921, PubMed:39142279, PubMed:40680746). Catalyzes 'Lys-63'-linked polyubiquitination of monoubiquitinated PCNA at 'Lys-164' in response to genotoxic stress, promoting error-free postreplication repair via template switching (PubMed:18316726, PubMed:18719106). Acts as an epigenetic regulator by promoting recruitment of DNMT1, thereby ensuring DNA methylation inheritance: specifically binds histone H3 trimethylated at 'Lys-9' (H3K9me3) and mediates histone H3 'Lys-23' polyubiquitination (H3K23ub), a docking site for DNMT1, leading to DNMT1 recruitment and replication-coupled DNA methylation maintenance (PubMed:40680746). Catalyzes formation of H3K23ub in two steps: first mediates monoubiquitination together with UBE2E1 and UBE2D2, and then extends ubiquitin chains via 'Lys-63'-linked ubiquitination together with UBE2N and UBE2V2 (PubMed:40680746). Also acts as a chromatin redodeling factor, thereby regulating transcription (PubMed:10391891, PubMed:1994885, PubMed:9126292). Exhibits ATP-dependent double-stranded DNA (dsDNA) translocase activity but lacks classical helicase activity; mediates replication fork reversal by concertedly unwinding and annealing nascent and parental strands, thereby suppressing DNA synthesis and maintaining genomic stability (PubMed:1994885). Resolves G-quadruplex (G4) DNA structures in cooperation with MSH2, limiting replication stress and G4 accumulation across the cell cycle (PubMed:39142279). Contributes to nucleotide excision repair by evicting lesion-containing oligonucleotides using its HIRAN and ATPase domains (PubMed:26051180). Can displace single-stranded DNA from triplex structures through ATP-dependent dsDNA translocation (PubMed:26051180, PubMed:31960921). Also has protein clearing activity at the stalled replication fork, facilitating restart of DNA replication (PubMed:21795603)","subunit":"Interacts with SP1 and SP3 independently of DNA; the interaction with these transcriptional factors may be required for basal transcription of target genes (PubMed:10391891). Interacts with EGR1; the interaction requires prior binding to DNA and represses c-Rel via a DNA looping mechanism (By similarity). Interacts with GATA4 (By similarity). Interacts with PCNA; the interaction promotes polyubiquitination of PCNA through association with the UBE2B-RAD18 and UBE2V2-UBE2N ubiquitin ligase complexes. Interacts with RAD18, SHPRH, UBE2V2 and UBE2N (PubMed:18316726, PubMed:18719106)","family":"Belongs to the SNF2/RAD54 helicase family. RAD16 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10391891","18316726","18719106","1994885","21795603","26051180","31960921","39142279","40680746","9126292"],"location":"Nucleus；Chromosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；细胞周期/分裂；注释原文：Functions as a DNA-dependent ATPase and E3 ubiquitin-protein ligase involved in chromatin regulation and DNA damage tolerance (DDT) (PubMed:18316726, PubMed:18719106, PubMed:26051180, PubMed:31960921, PubMed:39142279, PubMed:40680746).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；细胞周期/分裂"},"HMBOX1":{"hgnc":"HGNC:26137","symbol":"HMBOX1","accessions":["Q6NT76"],"name":"Homeobox-containing protein 1","length":"420","function":"Binds directly to 5'-TTAGGG-3' repeats in telomeric DNA (PubMed:23685356, PubMed:23813958). Associates with the telomerase complex at sites of active telomere processing and positively regulates telomere elongation (PubMed:23685356). Important for TERT binding to chromatin, indicating a role in recruitment of the telomerase complex to telomeres (By similarity). Also plays a role in the alternative lengthening of telomeres (ALT) pathway in telomerase-negative cells where it promotes formation and/or maintenance of ALT-associated promyelocytic leukemia bodies (APBs) (PubMed:23813958). Enhances formation of telomere C-circles in ALT cells, suggesting a possible role in telomere recombination (PubMed:23813958). Might also be involved in the DNA damage response at telomeres (PubMed:23813958)","subunit":"Associates with the telomerase holoenzyme complex. Interacts with DKC1, XRCC6 and COIL","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["23685356","23813958"],"location":"Nucleus；Cytoplasm；Chromosome, telomere；Nucleus, Cajal body；Nucleus, PML body","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；DNA修复/复制；注释原文：Binds directly to 5'-TTAGGG-3' repeats in telomeric DNA (PubMed:23685356, PubMed:23813958).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；DNA修复/复制"},"HMG20A":{"hgnc":"HGNC:5001","symbol":"HMG20A","accessions":["Q9NP66"],"name":"High mobility group protein 20A","length":"347","function":"Plays a role in neuronal differentiation as chromatin-associated protein. Acts as inhibitor of HMG20B. Overcomes the repressive effects of the neuronal silencer REST and induces the activation of neuronal-specific genes. Involved in the recruitment of the histone methyltransferase KMT2A/MLL1 and consequent increased methylation of histone H3 lysine 4 (By similarity)","subunit":"Interacts with DTNB","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；发育/分化；注释原文：Plays a role in neuronal differentiation as chromatin-associated protein.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"染色质/转录调控；发育/分化"},"HMGA1":{"hgnc":"HGNC:5010","symbol":"HMGA1","accessions":["P17096"],"name":"High mobility group protein HMG-I/HMG-Y","length":"107","function":"HMG-I/Y bind preferentially to the minor groove of A+T rich regions in double-stranded DNA. It is suggested that these proteins could function in nucleosome phasing and in the 3'-end processing of mRNA transcripts. They are also involved in the transcription regulation of genes containing, or in close proximity to A+T-rich regions","subunit":"Interacts with HIPK2 (By similarity)","family":"Belongs to the HMGA family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus；Chromosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；注释原文：HMG-I/Y bind preferentially to the minor groove of A+T rich regions in double-stranded DNA.","function_evidence":"数据库整理/推断；按原文限定；","categories":"染色质/转录调控"},"HMGB1":{"hgnc":"HGNC:4983","symbol":"HMGB1","accessions":["P09429"],"name":"High mobility group protein B1","length":"215","function":"Multifunctional redox sensitive protein with various roles in different cellular compartments. In the nucleus is one of the major chromatin-associated non-histone proteins and acts as a DNA chaperone involved in replication, transcription, chromatin remodeling, V(D)J recombination, DNA repair and genome stability (PubMed:33147444). Proposed to be an universal biosensor for nucleic acids. Promotes host inflammatory response to sterile and infectious signals and is involved in the coordination and integration of innate and adaptive immune responses. In the cytoplasm functions as a sensor and/or chaperone for immunogenic nucleic acids implicating the activation of TLR9-mediated immune responses, and mediates autophagy. Acts as a danger-associated molecular pattern (DAMP) molecule that amplifies immune responses during tissue injury (PubMed:27362237). Released to the extracellular environment can bind DNA, nucleosomes, IL-1 beta, CXCL12, AGER isoform 2/sRAGE, lipopolysaccharide (LPS) and lipoteichoic acid (LTA), and activates cells through engagement of multiple surface receptors (PubMed:34743181). In the extracellular compartment fully reduced HMGB1 (released by necrosis) acts as a chemokine, disulfide HMGB1 (actively secreted) as a cytokine, and sulfonyl HMGB1 (released from apoptotic cells) promotes immunological tolerance (PubMed:23446148, PubMed:23519706, PubMed:23994764, PubMed:25048472). Has proangiogdenic activity (By similarity). May be involved in platelet activation (By similarity). Binds to phosphatidylserine and phosphatidylethanolamide (By similarity). Bound to RAGE mediates signaling for neuronal outgrowth (By similarity). May play a role in accumulation of expanded polyglutamine (polyQ) proteins such as huntingtin (HTT) or TBP (PubMed:23303669, PubMed:25549101)\nNuclear functions are attributed to fully reduced HGMB1. Associates with chromatin and binds DNA with a preference to non-canonical DNA structures such as single-stranded DNA, DNA-containing cruciforms or bent structures, supercoiled DNA and ZDNA. Can bent DNA and enhance DNA flexibility by looping thus providing a mechanism to promote activities on various gene promoters by enhancing transcription factor binding and/or bringing distant regulatory sequences into close proximity (PubMed:20123072). May have an enhancing role in nucleotide excision repair (NER) (By similarity). However, effects in NER using in vitro systems have been reported conflictingly (PubMed:19360789, PubMed:19446504). May be involved in mismatch repair (MMR) and base excision repair (BER) pathways (PubMed:15014079, PubMed:16143102, PubMed:17803946). May be involved in double strand break repair such as non-homologous end joining (NHEJ) (By similarity). Involved in V(D)J recombination by acting as a cofactor of the RAG complex: acts by stimulating cleavage and RAG protein binding at the 23 bp spacer of conserved recombination signal sequences (RSS) (By similarity). In vitro can displace histone H1 from highly bent DNA (By similarity). Can restructure the canonical nucleosome leading to relaxation of structural constraints for transcription factor-binding (By similarity). Enhances binding of sterol regulatory element-binding proteins (SREBPs) such as SREBF1 to their cognate DNA sequences and increases their transcriptional activities (By similarity). Facilitates binding of TP53 to DNA (PubMed:23063560). Proposed to be involved in mitochondrial quality control and autophagy in a transcription-dependent fashion implicating HSPB1; however, this function has been questioned (By similarity). Can modulate the activity of the telomerase complex and may be involved in telomere maintenance (By similarity)\nIn the cytoplasm proposed to dissociate the BECN1:BCL2 complex via competitive interaction with BECN1 leading to autophagy activation (PubMed:20819940). Involved in oxidative stress-mediated autophagy (PubMed:21395369). Can protect BECN1 and ATG5 from calpain-mediated cleavage and thus proposed to control their proautophagic and proapoptotic functions and to regulate the extent and severity of inflammation-associated cellular injury (By similarity). In myeloid cells has a protective role against endotoxemia and bacterial infection by promoting autophagy (By similarity). Involved in endosomal translocation and activation of TLR9 in response to CpG-DNA in macrophages (By similarity)\nIn the extracellular compartment (following either active secretion or passive release) involved in regulation of the inflammatory response. Fully reduced HGMB1 (which subsequently gets oxidized after release) in association with CXCL12 mediates the recruitment of inflammatory cells during the initial phase of tissue injury; the CXCL12:HMGB1 complex triggers CXCR4 homodimerization (PubMed:22370717). Induces the migration of monocyte-derived immature dendritic cells and seems to regulate adhesive and migratory functions of neutrophils implicating AGER/RAGE and ITGAM (By similarity). Can bind to various types of DNA and RNA including microbial unmethylated CpG-DNA to enhance the innate immune response to nucleic acids. Proposed to act in promiscuous DNA/RNA sensing which cooperates with subsequent discriminative sensing by specific pattern recognition receptors (By similarity). Promotes extracellular DNA-induced AIM2 inflammasome activation implicating AGER/RAGE (PubMed:24971542). Disulfide HMGB1 binds to transmembrane receptors, such as AGER/RAGE, TLR2, TLR4 and probably TREM1, thus activating their signal transduction pathways. Mediates the release of cytokines/chemokines such as TNF, IL-1, IL-6, IL-8, CCL2, CCL3, CCL4 and CXCL10 (PubMed:12765338, PubMed:18354232, PubMed:19264983, PubMed:20547845, PubMed:24474694). Promotes secretion of interferon-gamma by macrophage-stimulated natural killer (NK) cells in concert with other cytokines like IL-2 or IL-12 (PubMed:15607795). TLR4 is proposed to be the primary receptor promoting macrophage activation and signaling through TLR4 seems to implicate LY96/MD-2 (PubMed:20547845). In bacterial LPS- or LTA-mediated inflammatory responses binds to the endotoxins and transfers them to CD14 for signaling to the respective TLR4:LY96 and TLR2 complexes (PubMed:18354232, PubMed:21660935, PubMed:25660311). Contributes to tumor proliferation by association with ACER/RAGE (By similarity). Can bind to IL1-beta and signals through the IL1R1:IL1RAP receptor complex (PubMed:18250463). Binding to class A CpG activates cytokine production in plasmacytoid dendritic cells implicating TLR9, MYD88 and AGER/RAGE and can activate autoreactive B cells. Via HMGB1-containing chromatin immune complexes may also promote B cell responses to endogenous TLR9 ligands through a B-cell receptor (BCR)-dependent and ACER/RAGE-independent mechanism (By similarity). Inhibits phagocytosis of apoptotic cells by macrophages; the function is dependent on poly-ADP-ribosylation and involves binding to phosphatidylserine on the cell surface of apoptotic cells (By similarity). In adaptive immunity may be involved in enhancing immunity through activation of effector T cells and suppression of regulatory T (TReg) cells (PubMed:15944249, PubMed:22473704). In contrast, without implicating effector or regulatory T-cells, required for tumor infiltration and activation of T-cells expressing the lymphotoxin LTA:LTB heterotrimer thus promoting tumor malignant progression (By similarity). Also reported to limit proliferation of T-cells (By similarity). Released HMGB1:nucleosome complexes formed during apoptosis can signal through TLR2 to induce cytokine production (PubMed:19064698). Involved in induction of immunological tolerance by apoptotic cells; its pro-inflammatory activities when released by apoptotic cells are neutralized by reactive oxygen species (ROS)-dependent oxidation specifically on Cys-106 (PubMed:18631454). During macrophage activation by activated lymphocyte-derived self apoptotic DNA (ALD-DNA) promotes recruitment of ALD-DNA to endosomes (By similarity)\n(Microbial infection) Critical for entry of human coronaviruses SARS-CoV and SARS-CoV-2, as well as human coronavirus NL63/HCoV-NL63 (PubMed:33147444). Regulates the expression of the pro-viral genes ACE2 and CTSL through chromatin modulation (PubMed:33147444). Required for SARS-CoV-2 ORF3A-induced reticulophagy which induces endoplasmic reticulum stress and inflammatory responses and facilitates viral infection (PubMed:35239449)\n(Microbial infection) Associates with the influenza A viral protein NP in the nucleus of infected cells, promoting viral growth and enhancing the activity of the viral polymerase\n(Microbial infection) Promotes Epstein-Barr virus (EBV) latent-to-lytic switch by sustaining the expression of the viral transcription factor BZLF1 that acts as a molecular switch to induce the transition from the latent to the lytic or productive phase of the virus cycle. Mechanistically, participates in EBV reactivation through the NLRP3 inflammasome\n(Microbial infection) Facilitates dengue virus propagation via interaction with the untranslated regions of viral genome. In turn, this interaction with viral RNA may regulate secondary structure of dengue RNA thus facilitating its recognition by the replication complex","subunit":"Interacts (fully reduced HMGB1) with CXCL12; probably in a 1:2 ratio involving two molecules of CXCL12, each interacting with one HMG box of HMGB1; inhibited by glycyrrhizin (PubMed:22370717). Associates with the TLR4:LY96 receptor complex (PubMed:20547845). Component of the RAG complex composed of core components RAG1 and RAG2, and associated component HMGB1 or HMGB2 (By similarity). Interacts (in cytoplasm upon starvation) with BECN1; inhibits the interaction of BECN1 and BCL2 leading to promotion of autophagy (PubMed:20819940). Interacts with KPNA1; involved in nuclear import (PubMed:17114460). Interacts with SREBF1, TLR2, TLR4, TLR9, PTPRZ1, APEX1, FEN1, POLB, TERT (By similarity). Interacts with IL1B, AGER, MSH2, XPA, XPC, HNF1A, TP53 (PubMed:15014079, PubMed:18160415, PubMed:18250463, PubMed:19446504, PubMed:23063560, PubMed:24474694). Interacts with CD24; the probable CD24:SIGLEC10 complex is proposed to inhibit HGMB1-mediated tissue damage immune response (PubMed:19264983). Interacts with THBD; prevents HGMB1 interaction with ACER/RAGE and inhibits HGMB1 pro-inflammatory activity (PubMed:15841214). Interacts with HAVCR2; impairs HMGB1 binding to B-DNA and likely HMGB1-mediated innate immune response (By similarity). Interacts with XPO1; mediating nuclear export (By similarity). Interacts with HTT (wild-type and mutant HTT with expanded polyglutamine repeat) (PubMed:23303669). Interacts with receptor RAGE/AGER (PubMed:34743181)\n(Microbial infection) Interacts with adenovirus protein pVII; this interaction immobilizes HMGB1 on chromatin, thus preventing its release from cell and subsequent inflammation activation\n(Microbial infection) Interacts with SARS-CoV-2 ORF3A protein; the interaction promotes association of HMGB1 with BECN1, promoting reticulophagy which induces endoplasmic reticulum stress and inflammatory responses and facilitates viral infection\n(Microbial infection) Interacts with influenza A virus protein NP; this interaction promotes viral replication","family":"Belongs to the HMGB family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12765338","15014079","15607795","15944249","16143102","17803946","18250463","18354232","18631454","19064698","19264983","19360789","19446504","20123072","20547845","20819940","21395369","21660935","22370717","22473704","22696656","23063560","23303669","23446148","23519706","23994764","24474694","24971542","25048472","25549101","25660311","27362237","33147444","34743181","34922257","34971702","35239449"],"location":"Nucleus；Chromosome；Cytoplasm；Secreted；Cell membrane；Peripheral membrane protein；Extracellular side；Endosome；Endoplasmic reticulum-Golgi intermediate compartment；Endoplasmic reticulum","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；DNA修复/复制；膜运输/高尔基/内吞；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；注释原文：Multifunctional redox sensitive protein with various roles in different cellular compartments.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269,ECO:0000305","categories":"染色质/转录调控；DNA修复/复制；膜运输/高尔基/内吞；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面"},"HMGB2":{"hgnc":"HGNC:5000","symbol":"HMGB2","accessions":["P26583"],"name":"High mobility group protein B2","length":"209","function":"Multifunctional protein with various roles in different cellular compartments. May act in a redox sensitive manner. In the nucleus is an abundant chromatin-associated non-histone protein involved in transcription, chromatin remodeling and V(D)J recombination and probably other processes. Binds DNA with a preference to non-canonical DNA structures such as single-stranded DNA. Can bent DNA and enhance DNA flexibility by looping thus providing a mechanism to promote activities on various gene promoters by enhancing transcription factor binding and/or bringing distant regulatory sequences into close proximity (PubMed:11909973, PubMed:18413230, PubMed:19522541, PubMed:19965638, PubMed:20123072, PubMed:7797075). Involved in V(D)J recombination by acting as a cofactor of the RAG complex: acts by stimulating cleavage and RAG protein binding at the 23 bp spacer of conserved recombination signal sequences (RSS) (By similarity). Proposed to be involved in the innate immune response to nucleic acids by acting as a promiscuous immunogenic DNA/RNA sensor which cooperates with subsequent discriminative sensing by specific pattern recognition receptors (By similarity). In the extracellular compartment acts as a chemokine. Promotes proliferation and migration of endothelial cells implicating AGER/RAGE (PubMed:19811285). Has antimicrobial activity in gastrointestinal epithelial tissues (PubMed:23877675). Involved in inflammatory response to antigenic stimulus coupled with pro-inflammatory activity (By similarity). Involved in modulation of neurogenesis probably by regulation of neural stem proliferation (By similarity). Involved in articular cartilage surface maintenance implicating LEF1 and the Wnt/beta-catenin pathway (By similarity)","subunit":"Interacts with POU2F2, POU2F1 and POU3F1 (By similarity). Component of the RAG complex composed of core components RAG1 and RAG2, and associated component HMGB1 or HMGB2 (By similarity). Component of the SET complex, composed of at least ANP32A, APEX1, HMGB2, NME1, SET and TREX1. Directly interacts with SET (PubMed:11909973). Interacts with LEF1 (By similarity)","family":"Belongs to the HMGB family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11909973","18413230","19522541","19811285","19965638","20123072","23877675","7797075"],"location":"Nucleus；Chromosome；Cytoplasm；Secreted","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；免疫/炎症/细胞死亡；黏附/受体/细胞表面；发育/分化；注释原文：Multifunctional protein with various roles in different cellular compartments.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269,ECO:0000305","categories":"染色质/转录调控；免疫/炎症/细胞死亡；黏附/受体/细胞表面；发育/分化"},"HMGB3":{"hgnc":"HGNC:5004","symbol":"HMGB3","accessions":["O15347"],"name":"High mobility group protein B3","length":"200","function":"Multifunctional protein with various roles in different cellular compartments. May act in a redox sensitive manner. Associates with chromatin and binds DNA with a preference for non-canonical DNA structures such as single-stranded DNA. Can bend DNA and enhance DNA flexibility by looping thus providing a mechanism to promote activities on various gene promoters (By similarity). Proposed to be involved in the innate immune response to nucleic acids by acting as a cytoplasmic promiscuous immunogenic DNA/RNA sensor (By similarity). Negatively regulates B-cell and myeloid cell differentiation. In hematopoietic stem cells may regulate the balance between self-renewal and differentiation. Involved in negative regulation of canonical Wnt signaling (By similarity)","subunit":"无可用SUBUNIT段","family":"Belongs to the HMGB family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus；Chromosome；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；免疫/炎症/细胞死亡；发育/分化；注释原文：Multifunctional protein with various roles in different cellular compartments.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"染色质/转录调控；免疫/炎症/细胞死亡；发育/分化"},"HMGN1":{"hgnc":"HGNC:4984","symbol":"HMGN1","accessions":["P05114"],"name":"Non-histone chromosomal protein HMG-14","length":"100","function":"Binds to the inner side of the nucleosomal DNA thus altering the interaction between the DNA and the histone octamer. May be involved in the process which maintains transcribable genes in a unique chromatin conformation. Inhibits the phosphorylation of nucleosomal histones H3 and H2A by RPS6KA5/MSK1 and RPS6KA3/RSK2 (By similarity)","subunit":"Interacts with transcriptional regulator SEHBP","family":"Belongs to the HMGN family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；激酶/磷酸化信号；注释原文：Binds to the inner side of the nucleosomal DNA thus altering the interaction between the DNA and the histone octamer.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"染色质/转录调控；激酶/磷酸化信号"},"HMGN2":{"hgnc":"HGNC:4986","symbol":"HMGN2","accessions":["P05204"],"name":"Non-histone chromosomal protein HMG-17","length":"90","function":"Binds to the inner side of the nucleosomal DNA thus altering the interaction between the DNA and the histone octamer. May be involved in the process which maintains transcribable genes in a unique chromatin conformation (By similarity)","subunit":"","family":"Belongs to the HMGN family","domains":[],"function_pmids":[],"location":"Nucleus; Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Binds to the inner side of the nucleosomal DNA thus altering the interaction between the DNA and the histone octamer. May be involved in the process which maintains transcribable genes in a unique chromatin conformation (By similarity)"},"HMGN3":{"hgnc":"HGNC:12312","symbol":"HMGN3","accessions":["Q15651"],"name":"High mobility group nucleosome-binding domain-containing protein 3","length":"99","function":"Binds to nucleosomes, regulating chromatin structure and consequently, chromatin-dependent processes such as transcription, DNA replication and DNA repair. Affects both insulin and glucagon levels and modulates the expression of pancreatic genes involved in insulin secretion. Regulates the expression of the glucose transporter SLC2A2 by binding specifically to its promoter region and recruiting PDX1 and additional transcription factors. Regulates the expression of SLC6A9, a glycine transporter which regulates the glycine concentration in synaptic junctions in the central nervous system, by binding to its transcription start site. May play a role in ocular development and astrocyte function (By similarity)","subunit":"Interacts with the ligand binding domain of the thyroid receptor (TR) (in vitro) (PubMed:7776974). Requires the presence of thyroid hormone for its interaction (PubMed:7776974). Interacts with transcriptional regulator SEHBP (PubMed:33468658). Interacts with nucleosomes (PubMed:11356838)","family":"Belongs to the HMGN family","domains":[],"function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Binds to nucleosomes, regulating chromatin structure and consequently, chromatin-dependent processes such as transcription, DNA replication and DNA repair. Affects both insulin and glucagon levels and modulates the expression of pancreatic genes involved in insulin secretion. Regulates the expression of the glucose transporter SLC2A2 by binding specifically to its promoter region and recruiting PDX1 and additional transcription factors. Regulates the expression of SLC6A9, a glycine transporter which regulates the glycine concentration in synaptic junctions in the central nervous system, by binding to its transcription start site. May play a role in ocular development and astrocyte function (By similarity)"},"HMGN4":{"hgnc":"HGNC:4989","symbol":"HMGN4","accessions":["O00479"],"name":"High mobility group nucleosome-binding domain-containing protein 4","length":"90","function":"","subunit":"","family":"Belongs to the HMGN family","domains":[],"function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":""},"HMGN5":{"hgnc":"HGNC:8013","symbol":"HMGN5","accessions":["P82970"],"name":"High mobility group nucleosome-binding domain-containing protein 5","length":"282","function":"Preferentially binds to euchromatin and modulates cellular transcription by counteracting linker histone-mediated chromatin compaction","subunit":"无可用SUBUNIT段","family":"Belongs to the HMGN family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；注释原文：Preferentially binds to euchromatin and modulates cellular transcription by counteracting linker histone-mediated chromatin compaction","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"染色质/转录调控"},"HMGXB3":{"hgnc":"HGNC:28982","symbol":"HMGXB3","accessions":["Q12766"],"name":"HMG domain-containing protein 3","length":"1292","function":"","subunit":"","family":"","domains":[],"function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":""},"HMGXB4":{"hgnc":"HGNC:5003","symbol":"HMGXB4","accessions":["Q9UGU5"],"name":"HMG domain-containing protein 4","length":"601","function":"Negatively regulates Wnt/beta-catenin signaling during development","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"发育/分化；注释原文：Negatively regulates Wnt/beta-catenin signaling during development","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"发育/分化"},"HNRNPA0":{"hgnc":"HGNC:5030","symbol":"HNRNPA0","accessions":["Q13151"],"name":"Heterogeneous nuclear ribonucleoprotein A0","length":"305","function":"mRNA-binding component of ribonucleosomes. Specifically binds AU-rich element (ARE)-containing mRNAs. Involved in post-transcriptional regulation of cytokines mRNAs","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12456657"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；注释原文：mRNA-binding component of ribonucleosomes.","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；染色质/转录调控"},"HNRNPA1":{"hgnc":"HGNC:5031","symbol":"HNRNPA1","accessions":["P09651"],"name":"Heterogeneous nuclear ribonucleoprotein A1","length":"372","function":"Involved in the packaging of pre-mRNA into hnRNP particles, transport of poly(A) mRNA from the nucleus to the cytoplasm and modulation of splice site selection (PubMed:17371836). Plays a role in the splicing of pyruvate kinase PKM by binding repressively to sequences flanking PKM exon 9, inhibiting exon 9 inclusion and resulting in exon 10 inclusion and production of the PKM M2 isoform (PubMed:20010808). Binds to the IRES and thereby inhibits the translation of the apoptosis protease activating factor APAF1 (PubMed:31498791). May bind to specific miRNA hairpins (PubMed:28431233)\n(Microbial infection) May play a role in HCV RNA replication\n(Microbial infection) Cleavage by Enterovirus 71 protease 3C results in increased translation of apoptosis protease activating factor APAF1, leading to apoptosis","subunit":"Identified in the spliceosome C complex (PubMed:11991638). Identified in a IGF2BP1-dependent mRNP granule complex containing untranslated mRNAs (PubMed:17289661). Interacts with SEPT6 (PubMed:17229681). Interacts with C9orf72 (PubMed:24549040). Interacts with KHDRBS1 (PubMed:17371836). Interacts with UBQLN2 (PubMed:25616961). Interacts with PPIA/CYPA (PubMed:25678563). Interacts (via the RGG-box) with the HOXB-AS3 peptide; the interaction inhibits binding of HNRNPA1 to the intronic sequences flanking exon 9 of the PKM gene, preventing inclusion of exon 9 and promoting inclusion of exon 10 which suppresses formation of the PKM M2 isoform and promotes production of the M1 isoform (PubMed:28985503)\n(Microbial infection) Interacts with HCV NS5B and with the 5'-UTR and 3'-UTR of HCV RNA\n(Microbial infection) May interact with SARS-CoV Nucleoprotein","family":"","domains":[],"function_pmids":["17229681","17371836","20010808","28431233","31498791"],"location":"Nucleus; Cytoplasm; Cytoplasm; Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Involved in the packaging of pre-mRNA into hnRNP particles, transport of poly(A) mRNA from the nucleus to the cytoplasm and modulation of splice site selection (PubMed:17371836). Plays a role in the splicing of pyruvate kinase PKM by binding repressively to sequences flanking PKM exon 9, inhibiting exon 9 inclusion and resulting in exon 10 inclusion and production of the PKM M2 isoform (PubMed:20010808). Binds to the IRES and thereby inhibits the translation of the apoptosis protease activating factor APAF1 (PubMed:31498791). May bind to specific miRNA hairpins (PubMed:28431233)\n(Microbial infection) May play a role in HCV RNA replication\n(Microbial infection) Cleavage by Enterovirus 71 protease 3C results in increased translation of apoptosis protease activating factor APAF1, leading to apoptosis"},"HNRNPA1L2":{"hgnc":"HGNC:27067","symbol":"HNRNPA1L2","accessions":["Q32P51"],"name":"Heterogeneous nuclear ribonucleoprotein A1-like 2","length":"320","function":"Involved in the packaging of pre-mRNA into hnRNP particles, transport of poly(A) mRNA from the nucleus to the cytoplasm and may modulate splice site selection","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；注释原文：Involved in the packaging of pre-mRNA into hnRNP particles, transport of poly(A) mRNA from the nucleus to the cytoplasm and may modulate splice site selection","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"RNA加工/剪接"},"HNRNPA1L3":{"hgnc":"HGNC:48778","symbol":"HNRNPA1L3","accessions":["A0A2R8Y4L2"],"name":"Heterogeneous nuclear ribonucleoprotein A1-like 3","length":"320","function":"","subunit":"","family":"","domains":[],"function_pmids":[],"location":"","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":""},"HNRNPA2B1":{"hgnc":"HGNC:5033","symbol":"HNRNPA2B1","accessions":["P22626"],"name":"Heterogeneous nuclear ribonucleoproteins A2/B1","length":"353","function":"Heterogeneous nuclear ribonucleoprotein (hnRNP) that associates with nascent pre-mRNAs, packaging them into hnRNP particles. The hnRNP particle arrangement on nascent hnRNA is non-random and sequence-dependent and serves to condense and stabilize the transcripts and minimize tangling and knotting. Packaging plays a role in various processes such as transcription, pre-mRNA processing, RNA nuclear export, subcellular location, mRNA translation and stability of mature mRNAs (PubMed:19099192). Forms hnRNP particles with at least 20 other different hnRNP and heterogeneous nuclear RNA in the nucleus. Involved in transport of specific mRNAs to the cytoplasm in oligodendrocytes and neurons: acts by specifically recognizing and binding the A2RE (21 nucleotide hnRNP A2 response element) or the A2RE11 (derivative 11 nucleotide oligonucleotide) sequence motifs present on some mRNAs, and promotes their transport to the cytoplasm (PubMed:10567417). Specifically binds single-stranded telomeric DNA sequences, protecting telomeric DNA repeat against endonuclease digestion (By similarity). Also binds other RNA molecules, such as primary miRNA (pri-miRNAs): acts as a nuclear 'reader' of the N6-methyladenosine (m6A) mark by specifically recognizing and binding a subset of nuclear m6A-containing pri-miRNAs. Binding to m6A-containing pri-miRNAs promotes pri-miRNA processing by enhancing binding of DGCR8 to pri-miRNA transcripts (PubMed:26321680). Involved in miRNA sorting into exosomes following sumoylation, possibly by binding (m6A)-containing pre-miRNAs (PubMed:24356509). Acts as a regulator of efficiency of mRNA splicing, possibly by binding to m6A-containing pre-mRNAs (PubMed:26321680). Plays a role in the splicing of pyruvate kinase PKM by binding repressively to sequences flanking PKM exon 9, inhibiting exon 9 inclusion and resulting in exon 10 inclusion and production of the PKM M2 isoform (PubMed:20010808). Also plays a role in the activation of the innate immune response (PubMed:31320558). Mechanistically, senses the presence of viral DNA in the nucleus, homodimerizes and is demethylated by JMJD6 (PubMed:31320558). In turn, translocates to the cytoplasm where it activates the TBK1-IRF3 pathway, leading to interferon alpha/beta production (PubMed:31320558)\n(Microbial infection) Involved in the transport of HIV-1 genomic RNA out of the nucleus, to the microtubule organizing center (MTOC), and then from the MTOC to the cytoplasm: acts by specifically recognizing and binding the A2RE (21 nucleotide hnRNP A2 response element) sequence motifs present on HIV-1 genomic RNA, and promotes its transport","subunit":"Homodimer; dimerization is required for nucleocytoplasmic translocation (PubMed:31320558). Identified in the spliceosome C complex (PubMed:11991638). Identified in a IGF2BP1-dependent mRNP granule complex containing untranslated mRNAs (PubMed:17289661). Interacts with IGF2BP1 (PubMed:17289661). Interacts with C9orf72 (PubMed:24549040). Interacts with DGCR8 (PubMed:26321680). Interacts with TARDBP (PubMed:19429692). Interacts with CKAP5 (PubMed:15703215). Interacts with TBK1 (PubMed:31320558). Interacts with STING1 (PubMed:31320558). Interacts with SRC (PubMed:31320558). Interacts with PPIA/CYPA (PubMed:25678563). Interacts (via C-terminus) with FAM76B; the interaction results in retention of HNRNPA2B1 in the nucleus and inhibition of the NF-kappa-B-mediated inflammatory pathway (PubMed:37643469). Interacts with NF-kappa-B inhibitors NFKBIA and NFKBIE; the interaction may be mediated by the RRM2 domain of HNRNPA2B1, and HNRNPA2B1 may interact simultaneously with FAM76B and either NFKBIA or NFKBIE to form a complex (PubMed:37643469). Interacts with CEP112 (PubMed:39349455)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10567417","15294897","17004321","19099192","20010808","24356509","26321680"],"location":"Nucleus；Nucleus, nucleoplasm；Cytoplasm；Cytoplasmic granule；Secreted, extracellular exosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；核质运输；染色质/转录调控；激酶/磷酸化信号；细胞骨架/纤毛；翻译/核糖体；免疫/炎症/细胞死亡；注释原文：Heterogeneous nuclear ribonucleoprotein (hnRNP) that associates with nascent pre-mRNAs, packaging them into hnRNP particles.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269,ECO:0000303","categories":"RNA加工/剪接；核质运输；染色质/转录调控；激酶/磷酸化信号；细胞骨架/纤毛；翻译/核糖体；免疫/炎症/细胞死亡"},"HNRNPA3":{"hgnc":"HGNC:24941","symbol":"HNRNPA3","accessions":["P51991"],"name":"Heterogeneous nuclear ribonucleoprotein A3","length":"378","function":"Plays a role in cytoplasmic trafficking of RNA. Binds to the cis-acting response element, A2RE. May be involved in pre-mRNA splicing","subunit":"Identified in the spliceosome C complex","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11886857"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；注释原文：Plays a role in cytoplasmic trafficking of RNA.","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接"},"HNRNPC":{"hgnc":"HGNC:5035","symbol":"HNRNPC","accessions":["P07910"],"name":"Heterogeneous nuclear ribonucleoproteins C1/C2","length":"306","function":"Binds pre-mRNA and nucleates the assembly of 40S hnRNP particles (PubMed:8264621). Interacts with poly-U tracts in the 3'-UTR or 5'-UTR of mRNA and modulates the stability and the level of translation of bound mRNA molecules (PubMed:12509468, PubMed:16010978, PubMed:7567451, PubMed:8264621). Single HNRNPC tetramers bind 230-240 nucleotides. Trimers of HNRNPC tetramers bind 700 nucleotides (PubMed:8264621). May play a role in the early steps of spliceosome assembly and pre-mRNA splicing. N6-methyladenosine (m6A) has been shown to alter the local structure in mRNAs and long non-coding RNAs (lncRNAs) via a mechanism named 'm(6)A-switch', facilitating binding of HNRNPC, leading to regulation of mRNA splicing (PubMed:25719671)","subunit":"Tetramer composed of 3 copies of isoform C1 and 1 copy of isoform C2. Assembly of 3 tetramers with bound pre-mRNA gives rise to a 19S complex that interacts with HNRNPA2B1 tetramers. Component of the 40S hnRNP particle. Identified in the spliceosome C complex. Interacts with IGF2BP1. Interacts with DHX9; this interaction is direct, enhanced probably by their concomitant binding to RNA and mediates the attachment to actin filaments (PubMed:11687588). Interacts with PPIA/CYPA (PubMed:25678563). Interacts with YWHAE (PubMed:37599448)","family":"Belongs to the RRM HNRPC family. RALY subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12509468","16010978","25719671","7567451","8264621"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；翻译/核糖体；注释原文：Binds pre-mRNA and nucleates the assembly of 40S hnRNP particles (PubMed:8264621).","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；翻译/核糖体"},"HNRNPCL1":{"hgnc":"HGNC:29295","symbol":"HNRNPCL1","accessions":["O60812"],"name":"Heterogeneous nuclear ribonucleoprotein C-like 1","length":"293","function":"May play a role in nucleosome assembly by neutralizing basic proteins such as A and B core hnRNPs","subunit":"无可用SUBUNIT段","family":"Belongs to the RRM HNRPC family. RALY subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；注释原文：May play a role in nucleosome assembly by neutralizing basic proteins such as A and B core hnRNPs","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"RNA加工/剪接；染色质/转录调控"},"HNRNPCL2":{"hgnc":"HGNC:48813","symbol":"HNRNPCL2","accessions":["B2RXH8"],"name":"Heterogeneous nuclear ribonucleoprotein C-like 2","length":"293","function":"May play a role in nucleosome assembly by neutralizing basic proteins such as A and B core hnRNPs","subunit":"","family":"Belongs to the RRM HNRPC family. RALY subfamily","domains":[],"function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"May play a role in nucleosome assembly by neutralizing basic proteins such as A and B core hnRNPs"},"HNRNPCL3":{"hgnc":"HGNC:51235","symbol":"HNRNPCL3","accessions":["B7ZW38"],"name":"Heterogeneous nuclear ribonucleoprotein C-like 3","length":"293","function":"","subunit":"","family":"Belongs to the RRM HNRPC family. RALY subfamily","domains":[],"function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"2","source_snapshot":"project UniProt records20261017/18","brief":""},"HNRNPCL4":{"hgnc":"HGNC:51333","symbol":"HNRNPCL4","accessions":["P0DMR1"],"name":"Heterogeneous nuclear ribonucleoprotein C-like 4","length":"293","function":"","subunit":"","family":"Belongs to the RRM HNRPC family. RALY subfamily","domains":[],"function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"2","source_snapshot":"project UniProt records20261017/18","brief":""},"HNRNPDL":{"hgnc":"HGNC:5037","symbol":"HNRNPDL","accessions":["O14979"],"name":"Heterogeneous nuclear ribonucleoprotein D-like","length":"420","function":"Acts as a transcriptional regulator. Promotes transcription repression. Promotes transcription activation in differentiated myotubes (By similarity). Binds to double- and single-stranded DNA sequences. Binds to the transcription suppressor CATR sequence of the COX5B promoter (By similarity). Binds with high affinity to RNA molecules that contain AU-rich elements (AREs) found within the 3'-UTR of many proto-oncogenes and cytokine mRNAs. Binds both to nuclear and cytoplasmic poly(A) mRNAs. Binds to poly(G) and poly(A), but not to poly(U) or poly(C) RNA homopolymers. Binds to the 5'-ACUAGC-3' RNA consensus sequence","subunit":"Interacts with ZNF148 (By similarity). Interacts with TNPO1","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["9538234"],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；注释原文：Acts as a transcriptional regulator.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"RNA加工/剪接；染色质/转录调控"},"HNRNPF":{"hgnc":"HGNC:5039","symbol":"HNRNPF","accessions":["P52597"],"name":"Heterogeneous nuclear ribonucleoprotein F","length":"415","function":"Component of the heterogeneous nuclear ribonucleoprotein (hnRNP) complexes which provide the substrate for the processing events that pre-mRNAs undergo before becoming functional, translatable mRNAs in the cytoplasm. Plays a role in the regulation of alternative splicing events. Binds G-rich sequences in pre-mRNAs and keeps target RNA in an unfolded state","subunit":"Identified in the spliceosome C complex. Interacts with AGO1, AGO2, TBP and TXNL4/DIM1","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["20526337"],"location":"Nucleus, nucleoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；注释原文：Component of the heterogeneous nuclear ribonucleoprotein (hnRNP) complexes which provide the substrate for the processing events that pre-mRNAs undergo before becoming functional, translatable mRNAs in the cytoplasm.","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接"},"HNRNPH2":{"hgnc":"HGNC:5042","symbol":"HNRNPH2","accessions":["P55795"],"name":"Heterogeneous nuclear ribonucleoprotein H2","length":"449","function":"This protein is a component of the heterogeneous nuclear ribonucleoprotein (hnRNP) complexes which provide the substrate for the processing events that pre-mRNAs undergo before becoming functional, translatable mRNAs in the cytoplasm. Binds poly(RG)","subunit":"Component of a ribonucleoprotein complex containing mRNAs and RNA-binding proteins including DDX5, HNRNPH2 and SRSF1 as well as splicing regulator ARVCF (PubMed:24644279). Interacts with TXNL4/DIM1 (PubMed:11054566)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus, nucleoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；注释原文：This protein is a component of the heterogeneous nuclear ribonucleoprotein (hnRNP) complexes which provide the substrate for the processing events that pre-mRNAs undergo before becoming functional, translatable mRNAs in the cytoplasm.","function_evidence":"数据库整理/推断；按原文限定；","categories":"RNA加工/剪接"},"HNRNPK":{"hgnc":"HGNC:5044","symbol":"HNRNPK","accessions":["P61978"],"name":"Heterogeneous nuclear ribonucleoprotein K","length":"463","function":"One of the major pre-mRNA-binding proteins. Binds tenaciously to poly(C) sequences. Likely to play a role in the nuclear metabolism of hnRNAs, particularly for pre-mRNAs that contain cytidine-rich sequences. Can also bind poly(C) single-stranded DNA. Plays an important role in p53/TP53 response to DNA damage, acting at the level of both transcription activation and repression. When sumoylated, acts as a transcriptional coactivator of p53/TP53, playing a role in p21/CDKN1A and 14-3-3 sigma/SFN induction. As far as transcription repression is concerned, acts by interacting with long intergenic RNA p21 (lincRNA-p21), a non-coding RNA induced by p53/TP53. This interaction is necessary for the induction of apoptosis, but not cell cycle arrest. As part of a ribonucleoprotein complex composed at least of ZNF827, HNRNPL and the circular RNA circZNF827 that nucleates the complex on chromatin, may negatively regulate the transcription of genes involved in neuronal differentiation (PubMed:33174841)","subunit":"Identified in the spliceosome C complex (PubMed:11991638). Part of a transcription inhibitory ribonucleoprotein complex composed at least of the circular RNA circZNF827, ZNF827 and HNRNPL (PubMed:33174841). Interacts with RBM42 and ZIK1 (By similarity). Interacts with BRDT (By similarity). Interacts with ANKRD28 (PubMed:16564677). Interacts with ASFV p30 protein (PubMed:18775702). Interacts with DDX1 (PubMed:12183465). Interacts with IVNS1ABP (via BACK domain); the interaction is direct (PubMed:23825951, PubMed:30538201). Interacts with PPIA/CYPA (PubMed:25678563)\n(Microbial infection) Interacts with HCV core protein (PubMed:9651361)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16360036","20673990","22825850","33174841"],"location":"Cytoplasm；Nucleus, nucleoplasm；Cell projection, podosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；DNA修复/复制；细胞周期/分裂；免疫/炎症/细胞死亡；线粒体/代谢；发育/分化；注释原文：One of the major pre-mRNA-binding proteins.","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；染色质/转录调控；DNA修复/复制；细胞周期/分裂；免疫/炎症/细胞死亡；线粒体/代谢；发育/分化"},"HNRNPL":{"hgnc":"HGNC:5045","symbol":"HNRNPL","accessions":["P14866"],"name":"Heterogeneous nuclear ribonucleoprotein L","length":"589","function":"Splicing factor binding to exonic or intronic sites and acting as either an activator or repressor of exon inclusion. Exhibits a binding preference for CA-rich elements (PubMed:11809897, PubMed:22570490, PubMed:24164894, PubMed:25623890, PubMed:26051023). Component of the heterogeneous nuclear ribonucleoprotein (hnRNP) complexes and associated with most nascent transcripts (PubMed:2687284). Associates, together with APEX1, to the negative calcium responsive element (nCaRE) B2 of the APEX2 promoter (PubMed:11809897). As part of a ribonucleoprotein complex composed at least of ZNF827, HNRNPK and the circular RNA circZNF827 that nucleates the complex on chromatin, may negatively regulate the transcription of genes involved in neuronal differentiation (PubMed:33174841). Regulates alternative splicing of a core group of genes involved in neuronal differentiation, likely by mediating H3K36me3-coupled transcription elongation and co-transcriptional RNA processing via interaction with CHD8","subunit":"Identified in a IGF2BP1-dependent mRNP granule complex containing untranslated mRNAs (PubMed:17289661). Interacts with HNRNPLL (PubMed:18669861). Interacts with APEX1; the interaction is DNA-dependent (PubMed:11809897). Component of a complex with SETD2 (PubMed:19332550, PubMed:36537238). Interacts with ELAVL1 (PubMed:18161049). Part of a transcription inhibitory ribonucleoprotein complex composed at least of the circular RNA circZNF827, ZNF827 and HNRNPK (PubMed:33174841). Interacts with CHD8 in an RNA-dependent manner. Interacts with FBXO16 (PubMed:34333526)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11809897","22570490","25623890","26051023","2687284","33174841","36537238"],"location":"Nucleus, nucleoplasm；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；发育/分化；注释原文：Splicing factor binding to exonic or intronic sites and acting as either an activator or repressor of exon inclusion.","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；染色质/转录调控；发育/分化"},"HNRNPLL":{"hgnc":"HGNC:25127","symbol":"HNRNPLL","accessions":["Q8WVV9"],"name":"Heterogeneous nuclear ribonucleoprotein L-like","length":"542","function":"RNA-binding protein that functions as a regulator of alternative splicing for multiple target mRNAs, including PTPRC/CD45 and STAT5A. Required for alternative splicing of PTPRC","subunit":"Interacts with HNRNPL","family":"","domains":[],"function_pmids":["18669861"],"location":"","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"RNA-binding protein that functions as a regulator of alternative splicing for multiple target mRNAs, including PTPRC/CD45 and STAT5A. Required for alternative splicing of PTPRC"},"HNRNPM":{"hgnc":"HGNC:5046","symbol":"HNRNPM","accessions":["P52272"],"name":"Heterogeneous nuclear ribonucleoprotein M","length":"730","function":"Pre-mRNA binding protein in vivo, binds avidly to poly(G) and poly(U) RNA homopolymers in vitro. Involved in splicing. Acts as a receptor for carcinoembryonic antigen in Kupffer cells, may initiate a series of signaling events leading to tyrosine phosphorylation of proteins and induction of IL-1 alpha, IL-6, IL-10 and tumor necrosis factor alpha cytokines","subunit":"Identified in the spliceosome C complex (PubMed:11991638). Interacts with PPIA/CYPA (PubMed:25678563)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA结合/剪接相关hnRNP；折叠状态与质量控制作用需区分。","function_evidence":"数据库整理/推断；按原文限定；","categories":"RNA加工/剪接；激酶/磷酸化信号；黏附/受体/细胞表面"},"HNRNPR":{"hgnc":"HGNC:5047","symbol":"HNRNPR","accessions":["O43390"],"name":"Heterogeneous nuclear ribonucleoprotein R","length":"633","function":"Component of ribonucleosomes, which are complexes of at least 20 other different heterogeneous nuclear ribonucleoproteins (hnRNP). hnRNP play an important role in processing of precursor mRNA in the nucleus","subunit":"Identified in the spliceosome C complex. Identified in a IGF2BP1-dependent mRNP granule complex containing untranslated mRNAs. Interacts with GTPBP1","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus；Microsome；Nucleus, nucleoplasm；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；注释原文：Component of ribonucleosomes, which are complexes of at least 20 other different heterogeneous nuclear ribonucleoproteins (hnRNP).","function_evidence":"数据库整理/推断；按原文限定；","categories":"RNA加工/剪接；染色质/转录调控"},"HNRNPU":{"hgnc":"HGNC:5048","symbol":"HNRNPU","accessions":["Q00839"],"name":"Heterogeneous nuclear ribonucleoprotein U","length":"825","function":"DNA- and RNA-binding protein involved in several cellular processes such as nuclear chromatin organization, telomere-length regulation, transcription, mRNA alternative splicing and stability, Xist-mediated transcriptional silencing and mitotic cell progression (PubMed:10490622, PubMed:18082603, PubMed:19029303, PubMed:22325991, PubMed:25986610, PubMed:28622508). Plays a role in the regulation of interphase large-scale gene-rich chromatin organization through chromatin-associated RNAs (caRNAs) in a transcription-dependent manner, and thereby maintains genomic stability (PubMed:1324173, PubMed:28622508, PubMed:8174554). Required for the localization of the long non-coding Xist RNA on the inactive chromosome X (Xi) and the subsequent initiation and maintenance of X-linked transcriptional gene silencing during X-inactivation (By similarity). Plays a role as a RNA polymerase II (Pol II) holoenzyme transcription regulator (PubMed:10490622, PubMed:15711563, PubMed:19617346, PubMed:23811339, PubMed:8174554, PubMed:9353307). Promotes transcription initiation by direct association with the core-TFIIH basal transcription factor complex for the assembly of a functional pre-initiation complex with Pol II in a actin-dependent manner (PubMed:10490622, PubMed:15711563). Blocks Pol II transcription elongation activity by inhibiting the C-terminal domain (CTD) phosphorylation of Pol II and dissociates from Pol II pre-initiation complex prior to productive transcription elongation (PubMed:10490622). Positively regulates CBX5-induced transcriptional gene silencing and retention of CBX5 in the nucleus (PubMed:19617346). Negatively regulates glucocorticoid-mediated transcriptional activation (PubMed:9353307). Key regulator of transcription initiation and elongation in embryonic stem cells upon leukemia inhibitory factor (LIF) signaling (By similarity). Involved in the long non-coding RNA H19-mediated Pol II transcriptional repression (PubMed:23811339). Participates in the circadian regulation of the core clock component BMAL1 transcription (By similarity). Plays a role in the regulation of telomere length (PubMed:18082603). Plays a role as a global pre-mRNA alternative splicing modulator by regulating U2 small nuclear ribonucleoprotein (snRNP) biogenesis (PubMed:22325991). Plays a role in mRNA stability (PubMed:17174306, PubMed:17289661, PubMed:19029303). Component of the CRD-mediated complex that promotes MYC mRNA stabilization (PubMed:19029303). Enhances the expression of specific genes, such as tumor necrosis factor TNFA, by regulating mRNA stability, possibly through binding to the 3'-untranslated region (UTR) (PubMed:17174306). Plays a role in mitotic cell cycle regulation (PubMed:21242313, PubMed:25986610). Involved in the formation of stable mitotic spindle microtubules (MTs) attachment to kinetochore, spindle organization and chromosome congression (PubMed:21242313). Phosphorylation at Ser-59 by PLK1 is required for chromosome alignement and segregation and progression through mitosis (PubMed:25986610). Also contributes to the targeting of AURKA to mitotic spindle MTs (PubMed:21242313). Binds to double- and single-stranded DNA and RNA, poly(A), poly(C) and poly(G) oligoribonucleotides (PubMed:1628625, PubMed:8068679, PubMed:8174554, PubMed:9204873, PubMed:9405365). Binds to chromatin-associated RNAs (caRNAs) (PubMed:28622508). Associates with chromatin to scaffold/matrix attachment region (S/MAR) elements in a chromatin-associated RNAs (caRNAs)-dependent manner (PubMed:10671544, PubMed:11003645, PubMed:11909954, PubMed:1324173, PubMed:28622508, PubMed:7509195, PubMed:9204873, PubMed:9405365). Binds to the Xist RNA (PubMed:26244333). Binds the long non-coding H19 RNA (PubMed:23811339). Binds to SMN1/2 pre-mRNAs at G/U-rich regions (PubMed:22325991). Binds to small nuclear RNAs (snRNAs) (PubMed:22325991). Binds to the 3'-UTR of TNFA mRNA (PubMed:17174306). Binds (via RNA-binding RGG-box region) to the long non-coding Xist RNA; this binding is direct and bridges the Xist RNA and the inactive chromosome X (Xi) (By similarity). Also negatively regulates embryonic stem cell differentiation upon LIF signaling (By similarity). Required for embryonic development (By similarity). Binds to brown fat long non-coding RNA 1 (Blnc1); facilitates the recruitment of Blnc1 by ZBTB7B required to drive brown and beige fat development and thermogenesis (By similarity)\n(Microbial infection) Negatively regulates immunodeficiency virus type 1 (HIV-1) replication by preventing the accumulation of viral mRNA transcripts in the cytoplasm","subunit":"Oligomer (via ATPase domain and RNA-binding RGG-box region); oligomerization occurs upon ATP-binding in a chromatin-associated RNAs (caRNAs)- and transcription-dependent manner and is required for chromatin decompaction (PubMed:28622508). ATP hydrolysis is required to cycle from an oligomeric to monomeric state to compact chromatin (PubMed:28622508). Component of the coding region determinant (CRD)-mediated complex, composed of DHX9, HNRNPU, IGF2BP1, SYNCRIP and YBX1 (PubMed:19029303). Identified in the spliceosome C complex (PubMed:11991638). Identified in a IGF2BP1-dependent mRNP granule complex containing untranslated mRNAs (PubMed:17289661, PubMed:19029303). Associates with heterogeneous nuclear ribonucleoprotein (hnRNP) particles (PubMed:11909954, PubMed:8174554, PubMed:9204873, PubMed:9405365). Associates (via middle region) with the C-terminal domain (CTD) RNA polymerase II (Pol II) holoenzyme; this association occurs in a RNA-independent manner (PubMed:10490622). Associates (via middle region) with the core-TFIIH basal transcription factor complex; this association inhibits the CTD phosphorylation of RNA polymerase II holoenzyme by down-regulating TFIIH kinase activity (PubMed:10490622). Associates with the telomerase holoenzyme complex (PubMed:18082603). Associates with spindle microtubules (MTs) in a TPX2-dependent manner (PubMed:21242313). Interacts (via C-terminus) with actin; this interaction is direct and mediates association with the phosphorylated CTD of RNA polymerase II and is disrupted in presence of the long non-coding H19 RNA (PubMed:15711563, PubMed:23811339). Interacts with AURKA (PubMed:21242313, PubMed:25986610). Interacts (via C-terminus) with CBX5; this interaction is, at least in part, RNA-dependent (PubMed:19617346). Interacts with CR2 (PubMed:7753047). Interacts with CRY1 (By similarity). Interacts (via C-terminus) with EP300; this interaction enhances DNA-binding to nuclear scaffold/matrix attachment region (S/MAR) elements (PubMed:11909954). Interacts with ERBB4 (PubMed:20858735). Interacts with GEMIN5 (PubMed:25911097). Interacts with IGF2BP1 (PubMed:17289661, PubMed:23640942). Interacts with IGF2BP2 and IGF2BP3 (PubMed:23640942). Interacts with NCL; this interaction occurs during mitosis (PubMed:21242313). Interacts (via C-terminus) with NR3C1 (via C-terminus) (PubMed:9353307). Interacts with PLK1; this interaction induces phosphorylation of HNRNPU at Ser-59 in mitosis (PubMed:25986610). Interacts with POU3F4 (PubMed:9105675). Interacts with SMARCA4; this interaction occurs in embryonic stem cells and stimulates global Pol II-mediated transcription. Interacts (via C-terminus) with TOP2A; this interaction protects the topoisomerase TOP2A from degradation and positively regulates the relaxation of supercoiled DNA by TOP2A in a RNA-dependent manner (By similarity). Interacts with TPX2; this interaction recruits HNRNPU to spindle microtubules (MTs) (PubMed:21242313, PubMed:25986610). Interacts with UBQLN2 (PubMed:25616961). Interacts (via RNA-binding RGG-box region) with ZBTB7B; the interaction facilitates the recruitment of long non-coding RNA Blnc1 by ZBTB7B (By similarity). Interacts with ERCC6 (PubMed:26030138)\n(Microbial infection) Interacts with HIV-1 protein Rev","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10490622","10671544","11003645","11909954","1324173","15711563","1628625","16916646","17174306","17289661","18082603","19029303","19617346","21242313","22325991","23811339","25986610","26244333","28622508","7509195","8068679","8174554","9204873","9353307","9405365"],"location":"Nucleus；Nucleus matrix；Chromosome；Nucleus speckle；Cytoplasm, cytoskeleton, microtubule organizing center, centrosome；Chromosome, centromere, kinetochore；Cytoplasm, cytoskeleton, spindle；Cytoplasm, cytoskeleton, spindle pole；Midbody；Cytoplasm；Cell surface；Cytoplasmic granule","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；发育/分化；注释原文：DNA- and RNA-binding protein involved in several cellular processes such as nuclear chromatin organization, telomere-length regulation, transcription, mRNA alternative splicing and stability, Xist-mediated transcriptional silencing and mitotic cell progression (PubMed:10490622, PubMed:18082603, PubMed:19029303, PubMed:22325991, PubMed:25986610, PubMed:28622508).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"RNA加工/剪接；染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；发育/分化"},"HNRNPUL1":{"hgnc":"HGNC:17011","symbol":"HNRNPUL1","accessions":["Q9BUJ2"],"name":"Heterogeneous nuclear ribonucleoprotein U-like protein 1","length":"856","function":"Acts as a basic transcriptional regulator (PubMed:12489984). Represses basic transcription driven by several virus and cellular promoters (PubMed:12489984). When associated with BRD7, activates transcription of glucocorticoid-responsive promoter in the absence of ligand-stimulation (PubMed:12489984). Also plays a role in mRNA processing and transport (PubMed:9733834). Binds avidly to poly(G) and poly(C) RNA homopolymers in vitro (PubMed:9733834)","subunit":"Binds RNA; this interaction is inhibited by high concentration of ATP (PubMed:9733834, PubMed:41971996). Interacts with the adenovirus type 5 (Ad5) E1B-55 kDa (PubMed:9733834). Interacts with NXF1 (PubMed:10668806). Interacts with PRMT2/HRMT1L1 (PubMed:11513728). Interacts with histones and BRD7 (PubMed:12489984). Interacts with TP53 (PubMed:15907477)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12489984","9733834"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；注释原文：Acts as a basic transcriptional regulator (PubMed:12489984).","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；染色质/转录调控"},"HNRNPUL2":{"hgnc":"HGNC:25451","symbol":"HNRNPUL2","accessions":["Q1KMD3"],"name":"Heterogeneous nuclear ribonucleoprotein U-like protein 2","length":"747","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"Binds to MLF1 and retains it in the nucleus","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"RNA加工/剪接"},"HOMEZ":{"hgnc":"HGNC:20164","symbol":"HOMEZ","accessions":["Q8IX15"],"name":"Homeobox and leucine zipper protein Homez","length":"550","function":"May function as a transcriptional regulator","subunit":"Homodimer or heterodimer (Potential). Interacts with HOXC8","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；注释原文：May function as a transcriptional regulator","function_evidence":"数据库整理/推断；按原文限定；","categories":"染色质/转录调控"},"HOOK1":{"hgnc":"HGNC:19884","symbol":"HOOK1","accessions":["Q9UJC3"],"name":"Protein Hook homolog 1","length":"728","function":"Component of the FTS/Hook/FHIP complex (FHF complex) (PubMed:18799622, PubMed:32073997). The FHF complex may function to promote vesicle trafficking and/or fusion via the homotypic vesicular protein sorting complex (the HOPS complex) (PubMed:18799622). FHF complex promotes the distribution of AP-4 complex to the perinuclear area of the cell (PubMed:32073997). Required for spermatid differentiation. Probably involved in the positioning of the microtubules of the manchette and the flagellum in relation to the membrane skeleton (By similarity)","subunit":"Self-associates (PubMed:18799622, PubMed:32073997). Component of the FTS/Hook/FHIP complex (FHF complex), composed of AKTIP/FTS, FHIP1B, and one or more members of the Hook family of proteins HOOK1, HOOK2, and HOOK3 (PubMed:18799622, PubMed:32073997). Interacts directly with AKTIP/FTS, HOOK2 and HOOK3 (PubMed:18799622, PubMed:32073997). Associates with several subunits of the homotypic vesicular sorting complex (the HOPS complex) including VPS16, VPS18, VPS39 and VPS41; these interactions may be indirect (PubMed:18799622). Interacts with CCDC181 (By similarity). Interacts (via coiled-coil region) with RIMBP3 (via C-terminus) (By similarity). Interacts with LRGUK (via guanylate kinase-like domain) (By similarity). Interacts with microtubules (PubMed:11238449). May interact with CLN3 (PubMed:15471887). Interacts with AP4M1; the interaction is direct, mediates the interaction between FTS-Hook-FHIP (FHF) complex and AP-4 and the perinuclear distribution of AP-4 (PubMed:32073997)","family":"Belongs to the hook family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["18799622","32073997"],"location":"Cytoplasm；Cytoplasm, cytoskeleton","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"膜运输/高尔基/内吞；细胞骨架/纤毛；发育/分化；注释原文：Component of the FTS/Hook/FHIP complex (FHF complex) (PubMed:18799622, PubMed:32073997).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"膜运输/高尔基/内吞；细胞骨架/纤毛；发育/分化"},"HOXA1":{"hgnc":"HGNC:5099","symbol":"HOXA1","accessions":["P49639"],"name":"Homeobox protein Hox-A1","length":"335","function":"Sequence-specific transcription factor (By similarity). Regulates multiple developmental processes including brainstem, inner and outer ear, abducens nerve and cardiovascular development and morphogenesis as well as cognition and behavior (PubMed:16155570). Also part of a developmental regulatory system that provides cells with specific positional identities on the anterior-posterior axis. Acts on the anterior body structures. Seems to act in the maintenance and/or generation of hindbrain segments (By similarity). Activates transcription in the presence of PBX1A and PKNOX1 (By similarity)","subunit":"Interacts with OGT (via TPR repeats domain); the interaction takes place mainly in the nucleus (By similarity). Forms a DNA-binding heterodimer with transcription factor PBX1 (PubMed:9191052)","family":"Belongs to the Antp homeobox family. Labial subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16155570"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；发育/分化；注释原文：Sequence-specific transcription factor (By similarity).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；发育/分化"},"HOXB5":{"hgnc":"HGNC:5116","symbol":"HOXB5","accessions":["P09067"],"name":"Homeobox protein Hox-B5","length":"269","function":"Sequence-specific transcription factor which is part of a developmental regulatory system that provides cells with specific positional identities on the anterior-posterior axis","subunit":"无可用SUBUNIT段","family":"Belongs to the Antp homeobox family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；发育/分化；注释原文：Sequence-specific transcription factor which is part of a developmental regulatory system that provides cells with specific positional identities on the anterior-posterior axis","function_evidence":"数据库整理/推断；按原文限定；","categories":"染色质/转录调控；发育/分化"},"HOXD13":{"hgnc":"HGNC:5136","symbol":"HOXD13","accessions":["P35453"],"name":"Homeobox protein Hox-D13","length":"343","function":"Sequence-specific transcription factor that binds gene promoters and activates their transcription (PubMed:24789103). Part of a developmental regulatory system that provides cells with specific positional identities on the anterior-posterior axis (By similarity)","subunit":"无可用SUBUNIT段","family":"Belongs to the Abd-B homeobox family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["24789103"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；发育/分化；注释原文：Sequence-specific transcription factor that binds gene promoters and activates their transcription (PubMed:24789103).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；发育/分化"},"HOXD3":{"hgnc":"HGNC:5137","symbol":"HOXD3","accessions":["P31249"],"name":"Homeobox protein Hox-D3","length":"432","function":"Sequence-specific transcription factor which is part of a developmental regulatory system that provides cells with specific positional identities on the anterior-posterior axis","subunit":"","family":"Belongs to the Antp homeobox family","domains":[],"function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Sequence-specific transcription factor which is part of a developmental regulatory system that provides cells with specific positional identities on the anterior-posterior axis"},"HOXD4":{"hgnc":"HGNC:5138","symbol":"HOXD4","accessions":["P09016"],"name":"Homeobox protein Hox-D4","length":"255","function":"Sequence-specific transcription factor which is part of a developmental regulatory system that provides cells with specific positional identities on the anterior-posterior axis","subunit":"Forms a DNA-binding heterodimer with transcription factor PBX1","family":"Belongs to the Antp homeobox family. Deformed subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；发育/分化；注释原文：Sequence-specific transcription factor which is part of a developmental regulatory system that provides cells with specific positional identities on the anterior-posterior axis","function_evidence":"数据库整理/推断；按原文限定；","categories":"染色质/转录调控；发育/分化"},"HP1BP3":{"hgnc":"HGNC:24973","symbol":"HP1BP3","accessions":["Q5SSJ5"],"name":"Heterochromatin protein 1-binding protein 3","length":"553","function":"Component of heterochromatin that maintains heterochromatin integrity during G1/S progression and regulates the duration of G1 phase to critically influence cell proliferative capacity (PubMed:24830416). Mediates chromatin condensation during hypoxia, leading to increased tumor cell viability, radio-resistance, chemo-resistance and self-renewal (PubMed:25100860)","subunit":"Interacts (via PxVxL motif) with CBX5 (via Trp-174)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["24830416","25100860"],"location":"Nucleus；Chromosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；注释原文：Component of heterochromatin that maintains heterochromatin integrity during G1/S progression and regulates the duration of G1 phase to critically influence cell proliferative capacity (PubMed:24830416).","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控"},"HPF1":{"hgnc":"HGNC:26051","symbol":"HPF1","accessions":["Q9NWY4"],"name":"Histone PARylation factor 1","length":"346","function":"Cofactor for serine ADP-ribosylation that confers serine specificity on PARP1 and PARP2 and plays a key role in DNA damage response (PubMed:28190768, PubMed:29480802, PubMed:29954836, PubMed:32028527, PubMed:32939087, PubMed:33186521, PubMed:33589610, PubMed:33683197, PubMed:34108479, PubMed:34210965, PubMed:34486521, PubMed:34625544, PubMed:34732825, PubMed:34795260, PubMed:34874266). Initiates the repair of double-strand DNA breaks: recruited to DNA damage sites by PARP1 and PARP2 and switches the amino acid specificity of PARP1 and PARP2 from aspartate or glutamate to serine residues, licensing serine ADP-ribosylation of target proteins (PubMed:28190768, PubMed:29480802, PubMed:29954836, PubMed:32028527, PubMed:32939087, PubMed:33589610, PubMed:33683197, PubMed:34486521, PubMed:34625544, PubMed:34732825, PubMed:34795260, PubMed:34874266). Serine ADP-ribosylation of target proteins, such as histones, promotes decompaction of chromatin and the recruitment of repair factors leading to the reparation of DNA strand breaks (PubMed:27067600, PubMed:28190768, PubMed:32939087, PubMed:33589610). Serine ADP-ribosylation of proteins constitutes the primary form of ADP-ribosylation of proteins in response to DNA damage (PubMed:29480802). HPF1 acts by completing the active site of PARP1 and PARP2: forms a composite active site composed of residues from HPF1 and PARP1 or PARP2 (PubMed:32028527, PubMed:33589610). While HPF1 promotes the initiation of serine ADP-ribosylation, it restricts the polymerase activity of PARP1 and PARP2 in order to limit the length of poly-ADP-ribose chains (PubMed:33683197, PubMed:34732825, PubMed:34795260). HPF1 also promotes tyrosine ADP-ribosylation, probably by conferring tyrosine specificity on PARP1 (PubMed:29954836, PubMed:30257210)","subunit":"Interacts with PARP1 (via the PARP catalytic domain) (PubMed:27067600, PubMed:32028527, PubMed:33589610). Interacts with PARP2 (via the PARP catalytic domain) (PubMed:27067600, PubMed:32028527, PubMed:32939087, PubMed:33141820, PubMed:34108479). Interacts with core nucleosomes in a PARP1- and PARP2-dependent manner (PubMed:27067600, PubMed:32939087)","family":"Belongs to the HPF1 family","domains":[],"function_pmids":["27067600","28190768","29480802","29954836","30257210","32028527","32939087","33186521","33589610","33683197","34108479","34210965","34486521","34625544","34732825","34795260","34874266"],"location":"Chromosome; Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Cofactor for serine ADP-ribosylation that confers serine specificity on PARP1 and PARP2 and plays a key role in DNA damage response (PubMed:28190768, PubMed:29480802, PubMed:29954836, PubMed:32028527, PubMed:32939087, PubMed:33186521, PubMed:33589610, PubMed:33683197, PubMed:34108479, PubMed:34210965, PubMed:34486521, PubMed:34625544, PubMed:34732825, PubMed:34795260, PubMed:34874266). Initiates the repair of double-strand DNA breaks: recruited to DNA damage sites by PARP1 and PARP2 and switches the amino acid specificity of PARP1 and PARP2 from aspartate or glutamate to serine residues, licensing serine ADP-ribosylation of target proteins (PubMed:28190768, PubMed:29480802, PubMed:29954836, PubMed:32028527, PubMed:32939087, PubMed:33589610, PubMed:33683197, PubMed:34486521, PubMed:34625544, PubMed:34732825, PubMed:34795260, PubMed:34874266). Serine ADP-ribosylation of target proteins, such as histones, promotes decompaction of chromatin and the recruitment of repair factors leading to the reparation of DNA strand breaks (PubMed:27067600, PubMed:28190768, PubMed:32939087, PubMed:33589610). Serine ADP-ribosylation of proteins constitutes the primary form of ADP-ribosylation of proteins in response to DNA damage (PubMed:29480802). HPF1 acts by completing the active site of PARP1 and PARP2: forms a composite active site composed of residues from HPF1 and PARP1 or PARP2 (PubMed:32028527, PubMed:33589610). While HPF1 promotes the initiation of serine ADP-ribosylation, it restricts the polymerase activity of PARP1 and PARP2 in order to limit the length of poly-ADP-ribose chains (PubMed:33683197, PubMed:34732825, PubMed:34795260). HPF1 also promotes tyrosine ADP-ribosylation, probably by conferring tyrosine specificity on PARP1 (PubMed:29954836, PubMed:30257210)"},"HPSE":{"hgnc":"HGNC:5164","symbol":"HPSE","accessions":["Q9Y251"],"name":"Heparanase","length":"543","function":"Endoglycosidase that cleaves heparan sulfate proteoglycans (HSPGs) into heparan sulfate side chains and core proteoglycans. Participates in extracellular matrix (ECM) degradation and remodeling. Selectively cleaves the linkage between a glucuronic acid unit and an N-sulfo glucosamine unit carrying either a 3-O-sulfo or a 6-O-sulfo group. Can also cleave the linkage between a glucuronic acid unit and an N-sulfo glucosamine unit carrying a 2-O-sulfo group, but not linkages between a glucuronic acid unit and a 2-O-sulfated iduronic acid moiety. It is essentially inactive at neutral pH but becomes active under acidic conditions such as during tumor invasion and in inflammatory processes. Facilitates cell migration associated with metastasis, wound healing and inflammation. Enhances shedding of syndecans, and increases endothelial invasion and angiogenesis in myelomas. Acts as a procoagulant by increasing the generation of activation factor X in the presence of tissue factor and activation factor VII. Increases cell adhesion to the extracellular matrix (ECM), independent of its enzymatic activity. Induces AKT1/PKB phosphorylation via lipid rafts increasing cell mobility and invasion. Heparin increases this AKT1/PKB activation. Regulates osteogenesis. Enhances angiogenesis through up-regulation of SRC-mediated activation of VEGF. Implicated in hair follicle inner root sheath differentiation and hair homeostasis","subunit":"Heterodimer; heterodimer formation between the 8 kDa and the 50 kDa subunits is required for enzyme activity. Interacts with TF; the interaction, inhibited by heparin, enhances the generation of activated factor X and activates coagulation. Interacts with HRG; the interaction is enhanced at acidic pH, partially inhibits binding of HPSE to cell surface receptors and modulates its enzymatic activity. Interacts with SDC1; the interaction enhances the shedding of SDC1. Interacts with HPSE2","family":"Belongs to the glycosyl hydrolase 79 family","domains":[],"function_pmids":["12213822","12773484","15044433","16452201","18557927","18798279","19244131","20097882","20181948","20309870","20561914","21131364"],"location":"Lysosome membrane; Secreted; Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Endoglycosidase that cleaves heparan sulfate proteoglycans (HSPGs) into heparan sulfate side chains and core proteoglycans. Participates in extracellular matrix (ECM) degradation and remodeling. Selectively cleaves the linkage between a glucuronic acid unit and an N-sulfo glucosamine unit carrying either a 3-O-sulfo or a 6-O-sulfo group. Can also cleave the linkage between a glucuronic acid unit and an N-sulfo glucosamine unit carrying a 2-O-sulfo group, but not linkages between a glucuronic acid unit and a 2-O-sulfated iduronic acid moiety. It is essentially inactive at neutral pH but becomes active under acidic conditions such as during tumor invasion and in inflammatory processes. Facilitates cell migration associated with metastasis, wound healing and inflammation. Enhances shedding of syndecans, and increases endothelial invasion and angiogenesis in myelomas. Acts as a procoagulant by increasing the generation of activation factor X in the presence of tissue factor and activation factor VII. Increases cell adhesion to the extracellular matrix (ECM), independent of its enzymatic activity. Induces AKT1/PKB phosphorylation via lipid rafts increasing cell mobility and invasion. Heparin increases this AKT1/PKB activation. Regulates osteogenesis. Enhances angiogenesis through up-regulation of SRC-mediated activation of VEGF. Implicated in hair follicle inner root sheath differentiation and hair homeostasis"},"HRAS":{"hgnc":"HGNC:5173","symbol":"HRAS","accessions":["P01112"],"name":"GTPase HRas","length":"189","function":"Signal transducer in the Ras-MAPK signaling pathway that regulates cell proliferation and survival (PubMed:22821884). Ras proteins bind GDP/GTP and possess intrinsic GTPase activity (PubMed:12740440, PubMed:14500341, PubMed:9020151). Recognized by LZTR1 that mediates its ubiquitination by a BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complex (PubMed:40934300)","subunit":"In its GTP-bound form interacts with PLCE1 (PubMed:11022048). Interacts with TBC1D10C (PubMed:17230191). Interacts with RGL3 (By similarity). Interacts with HSPD1 (By similarity). Found in a complex with at least BRAF, HRAS, MAP2K1, MAPK3 and RGS14 (By similarity). Interacts (active GTP-bound form) with RGS14 (via RBD 1 domain) (By similarity). Forms a signaling complex with RASGRP1 and DGKZ (PubMed:11257115). Interacts with RASSF5 (PubMed:18596699). Interacts with PDE6D (PubMed:11980706). Interacts with IKZF3 (PubMed:10369681). Interacts with RACK1 (PubMed:14500341). Interacts with PIK3CG; the interaction is required for membrane recruitment and beta-gamma G protein dimer-dependent activation of the PI3K gamma complex PIK3CG:PIK3R6 (By similarity). Interacts with RAPGEF2 (PubMed:10608844, PubMed:11598133). Interacts (active GTP-bound form) with both SHOC2 and PP1c (all isoforms) to form a tertiary complex; SHOC2 and PP1c preferably bind M-Ras/MRAS, but they also bind K-Ras/KRAS, N-Ras/NRAS and H-Ras/HRAS (PubMed:35768504, PubMed:35831509, PubMed:36175670). Interacts (GTP-bound form) with MAPKAP1/SIN1; inhibiting H-Ras/HRAS activity (PubMed:35522713). Interacts (GDP-bound form) with LZTR1; this interaction mediates HRAS ubiquitination by BCR E3 ligase complex (PubMed:40934300)","family":"Belongs to the small GTPase superfamily. Ras family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12740440","14500341","22821884","40934300","9020151"],"location":"Cell membrane；Lipid-anchor；Cytoplasmic side；Golgi apparatus；Golgi apparatus membrane；Nucleus；Cytoplasm；Cytoplasm, perinuclear region","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；注释原文：Signal transducer in the Ras-MAPK signaling pathway that regulates cell proliferation and survival (PubMed:22821884).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态"},"HRCT1":{"hgnc":"HGNC:33872","symbol":"HRCT1","accessions":["Q6UXD1"],"name":"Histidine-rich carboxyl terminus protein 1","length":"115","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Membrane; Single-pass membrane protein","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"HS1BP3":{"hgnc":"HGNC:24979","symbol":"HS1BP3","accessions":["Q53T59"],"name":"HCLS1-binding protein 3","length":"392","function":"May be a modulator of IL-2 signaling","subunit":"Binds HCLS1. Interacts with the SH3 domain of HCLS1 in vitro (By similarity)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"；注释原文：May be a modulator of IL-2 signaling","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"未归类"},"HSBP1":{"hgnc":"HGNC:5203","symbol":"HSBP1","accessions":["O75506"],"name":"Heat shock factor-binding protein 1","length":"76","function":"Negative regulator of the heat shock response. Negatively affects HSF1 DNA-binding activity. May have a role in the suppression of the activation of the stress response during the aging process","subunit":"Homohexamer. Associates with heptad repeats of HSF1 trimers and probably also HSF1 monomers, and with HSP70. Association with HSF1 trimers and HSP70 coincides with attenuation of heat shock response and the conversion of HSF1 trimer to monomer","family":"Belongs to the HSBP1 family","domains":[],"function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Negative regulator of the heat shock response. Negatively affects HSF1 DNA-binding activity. May have a role in the suppression of the activation of the stress response during the aging process"},"HSBP1L1":{"hgnc":"HGNC:37243","symbol":"HSBP1L1","accessions":["C9JCN9"],"name":"Heat shock factor-binding protein 1-like protein 1","length":"74","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"Belongs to the HSBP1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"HSF1":{"hgnc":"HGNC:5224","symbol":"HSF1","accessions":["Q00613"],"name":"Heat shock factor protein 1","length":"529","function":"Functions as a stress-inducible and DNA-binding transcription factor that plays a central role in the transcriptional activation of the heat shock response (HSR), leading to the expression of a large class of molecular chaperones, heat shock proteins (HSPs), that protect cells from cellular insult damage (PubMed:11447121, PubMed:12659875, PubMed:12917326, PubMed:15016915, PubMed:18451878, PubMed:1871105, PubMed:1986252, PubMed:25963659, PubMed:26754925, PubMed:7623826, PubMed:7760831, PubMed:8940068, PubMed:8946918, PubMed:9121459, PubMed:9341107, PubMed:9499401, PubMed:9535852, PubMed:9727490). In unstressed cells, is present in a HSP90-containing multichaperone complex that maintains it in a non-DNA-binding inactivated monomeric form (PubMed:11583998, PubMed:16278218, PubMed:9727490). Upon exposure to heat and other stress stimuli, undergoes homotrimerization and activates HSP gene transcription through binding to site-specific heat shock elements (HSEs) present in the promoter regions of HSP genes (PubMed:10359787, PubMed:11583998, PubMed:12659875, PubMed:16278218, PubMed:1871105, PubMed:1986252, PubMed:25963659, PubMed:26754925, PubMed:7623826, PubMed:7935471, PubMed:8455624, PubMed:8940068, PubMed:9499401, PubMed:9727490). Upon heat shock stress, forms a chromatin-associated complex with TTC5/STRAP and p300/EP300 to stimulate HSR transcription, therefore increasing cell survival (PubMed:18451878). Activation is reversible, and during the attenuation and recovery phase period of the HSR, returns to its unactivated form (PubMed:11583998, PubMed:16278218). Binds to inverted 5'-NGAAN-3' pentamer DNA sequences (PubMed:1986252, PubMed:26727489). Binds to chromatin at heat shock gene promoters (PubMed:25963659). Activates transcription of transcription factor FOXR1 which in turn activates transcription of the heat shock chaperones HSPA1A and HSPA6 and the antioxidant NADPH-dependent reductase DHRS2 (PubMed:34723967). Also serves several other functions independently of its transcriptional activity. Involved in the repression of Ras-induced transcriptional activation of the c-fos gene in heat-stressed cells (PubMed:9341107). Positively regulates pre-mRNA 3'-end processing and polyadenylation of HSP70 mRNA upon heat-stressed cells in a symplekin (SYMPK)-dependent manner (PubMed:14707147). Plays a role in nuclear export of stress-induced HSP70 mRNA (PubMed:17897941). Plays a role in the regulation of mitotic progression (PubMed:18794143). Also plays a role as a negative regulator of non-homologous end joining (NHEJ) repair activity in a DNA damage-dependent manner (PubMed:26359349). Involved in stress-induced cancer cell proliferation in a IER5-dependent manner (PubMed:26754925)\n(Microbial infection) Plays a role in latent human immunodeficiency virus (HIV-1) transcriptional reactivation. Binds to the HIV-1 long terminal repeat promoter (LTR) to reactivate viral transcription by recruiting cellular transcriptional elongation factors, such as CDK9, CCNT1 and EP300","subunit":"Monomer; cytoplasmic latent and transcriptionally inactive monomeric form in unstressed cells (PubMed:11583998, PubMed:7623826, PubMed:7935376, PubMed:7935471, PubMed:8455624, PubMed:9222587, PubMed:9727490). Homotrimer; in response to stress, such as heat shock, homotrimerizes and translocates into the nucleus, binds to heat shock element (HSE) sequences in promoter of heat shock protein (HSP) genes and acquires transcriptional ability (PubMed:11583998, PubMed:26727489, PubMed:26754925, PubMed:7623826, PubMed:7935471, PubMed:8455624, PubMed:9222587, PubMed:9727490). Interacts (via monomeric form) with FKBP4; this interaction occurs in unstressed cells (PubMed:11583998). Associates (via monomeric form) with HSP90 proteins in a multichaperone complex in unnstressed cell; this association maintains HSF1 in a non-DNA-binding and transcriptional inactive form by preventing HSF1 homotrimerization (PubMed:11583998, PubMed:15661742, PubMed:16278218, PubMed:9727490). Homotrimeric transactivation activity is modulated by protein-protein interactions and post-translational modifications (PubMed:11583998, PubMed:15016915, PubMed:16554823, PubMed:26754925). Interacts with HSP90AA1; this interaction is decreased in a IER5-dependent manner, promoting HSF1 accumulation in the nucleus, homotrimerization and DNA-binding activities (PubMed:26754925). Part (via regulatory domain in the homotrimeric form) of a large heat shock-induced HSP90-dependent multichaperone complex at least composed of FKBP4, FKBP5, HSP90 proteins, PPID, PPP5C and PTGES3; this association maintains the HSF1 homotrimeric DNA-bound form in a transcriptionally inactive form (PubMed:11583998, PubMed:16278218, PubMed:9727490). Interacts with BAG3 (via BAG domain); this interaction occurs in normal and heat-shocked cells promoting nuclear shuttling of HSF1 in a BAG3-dependent manner (PubMed:26159920). Interacts (via homotrimeric and hyperphosphorylated form) with FKBP4; this interaction occurs upon heat shock in a HSP90-dependent multichaperone complex (PubMed:11583998). Interacts (via homotrimeric form preferentially) with EEF1A proteins (PubMed:15016915). In heat shocked cells, stress-denatured proteins compete with HSF1 homotrimeric DNA-bound form for association of the HSP90-dependent multichaperone complex, and hence alleviating repression of HSF1-mediated transcriptional activity (PubMed:11583998). Interacts (via homotrimeric form preferentially) with DAXX; this interaction relieves homotrimeric HSF1 from repression of its transcriptional activity by HSP90-dependent multichaperone complex upon heat shock (PubMed:15016915). Interacts (via D domain and preferentially with hyperphosphorylated form) with JNK1; this interaction occurs under both normal growth conditions and immediately upon heat shock (PubMed:10747973). Interacts (via D domain and preferentially with hyperphosphorylated form) with MAPK3; this interaction occurs upon heat shock (PubMed:10747973). Interacts with IER5 (via central region); this interaction promotes PPP2CA-induced dephosphorylation on Ser-121, Ser-307, Ser-314, Thr-323 and Thr-367 and HSF1 transactivation activity (PubMed:25816751, PubMed:26496226, PubMed:26754925). Found in a ribonucleoprotein complex composed of the HSF1 homotrimeric form, translation elongation factor eEF1A proteins and non-coding RNA heat shock RNA-1 (HSR1); this complex occurs upon heat shock and stimulates HSF1 DNA-binding activity (PubMed:16554823). Interacts (via transactivation domain) with HSPA1A/HSP70 and DNAJB1; these interactions result in the inhibition of heat shock- and HSF1-induced transcriptional activity during the attenuation and recovery phase from heat shock (PubMed:7935376, PubMed:9222587, PubMed:9499401). Interacts (via Ser-303 and Ser-307 phosphorylated form) with YWHAE; this interaction promotes HSF1 sequestration in the cytoplasm in an ERK-dependent manner (PubMed:12917326). Found in a complex with IER5 and PPP2CA (PubMed:26754925). Interacts with TPR; this interaction increases upon heat shock and stimulates export of HSP70 mRNA (PubMed:17897941). Interacts with SYMPK (via N-terminus) and CSTF2; these interactions occur upon heat shock (PubMed:14707147). Interacts (via transactivation domain) with HSPA8 (PubMed:9499401). Interacts with EEF1D; this interaction occurs at heat shock promoter element (HSE) sequences (PubMed:21597468). Interacts with MAPKAPK2 (PubMed:16278218). Interacts with PRKACA/PKA (PubMed:21085490). Interacts (via transactivation domain) with GTF2A2 (PubMed:11005381). Interacts (via transactivation domain) with GTF2B (PubMed:11005381). Interacts (via transactivation domain) with TBP (PubMed:11005381). Interacts with CDK9, CCNT1 and EP300 (PubMed:27189267). Interacts (via N-terminus) with XRCC5 (via N-terminus) and XRCC6 (via N-terminus); these interactions are direct and prevent XRCC5/XRCC6 heterodimeric binding and non-homologous end joining (NHEJ) repair activities induced by ionizing radiation (IR) (PubMed:26359349). Interacts with PLK1; this interaction occurs during the early mitotic period, increases upon heat shock but does not modulate neither HSF1 homotrimerization and DNA-binding activities (PubMed:15661742, PubMed:18794143). Interacts (via Ser-216 phosphorylated form) with CDC20; this interaction occurs in mitosis in a MAD2L1-dependent manner and prevents PLK1-stimulated degradation of HSF1 by blocking the recruitment of the SCF(BTRC) ubiquitin ligase complex (PubMed:18794143). Interacts with MAD2L1; this interaction occurs in mitosis (PubMed:18794143). Interacts with BTRC; this interaction occurs during mitosis, induces its ubiquitin-dependent degradation following stimulus-dependent phosphorylation at Ser-216, a process inhibited by CDC20 (PubMed:18794143). Interacts with HSP90AA1 and HSP90AB1 (PubMed:26517842). Forms a complex with TTC5/STRAP and p300/EP300; these interactions augment chromatin-bound HSF1 and p300/EP300 histone acetyltransferase activity (PubMed:18451878)","family":"Belongs to the HSF family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10359787","11447121","11583998","12659875","12917326","14707147","15016915","16278218","17897941","18451878","1871105","18794143","1986252","25963659","26359349","26727489","26754925","27189267","34723967","7623826","7760831","7935471","8455624","8940068","8946918","9121459","9341107","9499401","9535852","9727490"],"location":"Nucleus；Cytoplasm；Nucleus, nucleoplasm；Cytoplasm, perinuclear region；Cytoplasm, cytoskeleton, spindle pole；Cytoplasm, cytoskeleton, microtubule organizing center, centrosome；Chromosome, centromere, kinetochore","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；核质运输；染色质/转录调控；DNA修复/复制；细胞周期/分裂；注释原文：Functions as a stress-inducible and DNA-binding transcription factor that plays a central role in the transcriptional activation of the heat shock response (HSR), leading to the expression of a large class of molecular chaperones, heat shock proteins (HSPs), that protect cells from cellular insult damage (PubMed:11447121, PubMed:12659875, PubMed:12917326, PubMed:15016915, PubMed:18451878, PubMed:1871105, PubMed:1986252, PubMed:25963659, PubMed:26754925, PubMed:7623826, PubMed:7760831, PubMed:8940068, PubMed:8946918, PubMed:9121459, PubMed:9341107, PubMed:9499401, PubMed:9535852, PubMed:9727490).","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；核质运输；染色质/转录调控；DNA修复/复制；细胞周期/分裂"},"HSF2":{"hgnc":"HGNC:5225","symbol":"HSF2","accessions":["Q03933"],"name":"Heat shock factor protein 2","length":"536","function":"DNA-binding protein that specifically binds heat shock promoter elements (HSE) and activates transcription. In higher eukaryotes, HSF is unable to bind to the HSE unless the cells are heat shocked","subunit":"DNA-binding homotrimer in stressed or heat shocked cells, otherwise found as a homodimer","family":"Belongs to the HSF family","domains":[],"function_pmids":[],"location":"Cytoplasm; Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"DNA-binding protein that specifically binds heat shock promoter elements (HSE) and activates transcription. In higher eukaryotes, HSF is unable to bind to the HSE unless the cells are heat shocked"},"HSF2BP":{"hgnc":"HGNC:5226","symbol":"HSF2BP","accessions":["O75031"],"name":"Heat shock factor 2-binding protein","length":"334","function":"Meiotic recombination factor component of recombination bridges involved in meiotic double-strand break repair. Modulates the localization of recombinases DMC1:RAD51 to meiotic double-strand break (DSB) sites through the interaction with BRCA2 and its recruitment during meiotic recombination (By similarity) (PubMed:31242413). Indispensable for the DSB repair, homologous synapsis, and crossover formation that are needed for progression past metaphase I, is essential for spermatogenesis and male fertility (By similarity). Required for proper recombinase recruitment in female meiosis (By similarity). Inhibits BNC1 transcriptional activity during spermatogenesis, probably by sequestering it in the cytoplasm (By similarity). May be involved in modulating HSF2 activation in testis (PubMed:9651507)","subunit":"Associates with HSF2 (PubMed:9651507). The interaction seems to occur between the trimerization domain of HSF2 and the N-terminal hydrophilic region of HSF2BP (PubMed:9651507). Interacts (via C-terminus) with BNC1 (By similarity). Interacts (via N-terminus) with BRCA2 and BRME1; the interactions are direct and allow the formation of a ternary complex. The complex BRME1:HSF2BP:BRCA2 interacts with SPATA22, MEIOB and RAD51 (By similarity) (PubMed:31242413)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["31242413","9651507"],"location":"Cytoplasm；Chromosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；发育/分化；注释原文：Meiotic recombination factor component of recombination bridges involved in meiotic double-strand break repair.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；发育/分化"},"HSF4":{"hgnc":"HGNC:5227","symbol":"HSF4","accessions":["Q9ULV5"],"name":"Heat shock factor protein 4","length":"492","function":"Heat-shock transcription factor that specifically binds heat shock promoter elements (HSE) (PubMed:22587838, PubMed:23507146). Required for denucleation and organelle rupture and degradation that occur during eye lens terminal differentiation, when fiber cells that compose the lens degrade all membrane-bound organelles in order to provide lens with transparency to allow the passage of light (By similarity). In this process, may regulate denucleation of lens fiber cells in part by activating DNASE2B transcription (By similarity). May be involved in DNA repair through the transcriptional regulation of RAD51 (PubMed:22587838). May up-regulate p53/TP53 protein in eye lens fiber cells, possibly through protein stabilization (PubMed:28981088). In the eye lens, controls the expression of alpha-crystallin B chain/CRYAB and consequently may be involved in the regulation of lysosomal acidification (By similarity)\nTranscriptional repressor\nTranscriptional activator","subunit":"Homotrimer (By similarity). Exhibits constitutive DNA binding and forms trimers even in the absence of stress (By similarity). Interacts with ALKBH4, DUSP26, MAPK1, MAPK2, MAPK8 and MAP kinase p38 (PubMed:16581800, PubMed:23145062)","family":"Belongs to the HSF family","domains":[],"function_pmids":["10488131","16371476","22587838","23507146","28981088"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Heat-shock transcription factor that specifically binds heat shock promoter elements (HSE) (PubMed:22587838, PubMed:23507146). Required for denucleation and organelle rupture and degradation that occur during eye lens terminal differentiation, when fiber cells that compose the lens degrade all membrane-bound organelles in order to provide lens with transparency to allow the passage of light (By similarity). In this process, may regulate denucleation of lens fiber cells in part by activating DNASE2B transcription (By similarity). May be involved in DNA repair through the transcriptional regulation of RAD51 (PubMed:22587838). May up-regulate p53/TP53 protein in eye lens fiber cells, possibly through protein stabilization (PubMed:28981088). In the eye lens, controls the expression of alpha-crystallin B chain/CRYAB and consequently may be involved in the regulation of lysosomal acidification (By similarity)\nTranscriptional repressor\nTranscriptional activator"},"HSFX3":{"symbol":"HSFX3","accessions":["A0A1B0GWH4"],"name":"Heat shock transcription factor, X-linked member 3","length":333,"function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","domains":"InterPro: IPR000232 HSF_DNA-bd\nInterPro: IPR036388 WH-like_DNA-bd_sf\nInterPro: IPR036390 WH_DNA-bd_sf\nPfam: PF00447 HSF_DNA-bind","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"染色质/转录调控","location":"Nucleus","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020"},"HSFX4":{"hgnc":"HGNC:52398","symbol":"HSFX4","accessions":["A0A1B0GTS1"],"name":"Heat shock transcription factor, X-linked member 4","length":"333","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"Belongs to the HSF family","domains":"DNA binding 79-182:  [ECO:0000250/UniProtKB/P10961]","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"染色质/转录调控"},"HSP90AA1":{"hgnc":"HGNC:5253","symbol":"HSP90AA1","accessions":["P07900"],"name":"Heat shock protein HSP 90-alpha","length":"732","function":"Molecular chaperone that promotes the maturation, structural maintenance and proper regulation of specific target proteins involved for instance in cell cycle control and signal transduction. Undergoes a functional cycle that is linked to its ATPase activity which is essential for its chaperone activity. This cycle probably induces conformational changes in the client proteins, thereby causing their activation. Interacts dynamically with various co-chaperones that modulate its substrate recognition, ATPase cycle and chaperone function (PubMed:11274138, PubMed:12526792, PubMed:15577939, PubMed:15937123, PubMed:27353360, PubMed:29127155). Engages with a range of client protein classes via its interaction with various co-chaperone proteins or complexes, that act as adapters, simultaneously able to interact with the specific client and the central chaperone itself (PubMed:29127155). Recruitment of ATP and co-chaperone followed by client protein forms a functional chaperone. After the completion of the chaperoning process, properly folded client protein and co-chaperone leave HSP90 in an ADP-bound partially open conformation and finally, ADP is released from HSP90 which acquires an open conformation for the next cycle (PubMed:26991466, PubMed:27295069). Plays a critical role in mitochondrial import, delivers preproteins to the mitochondrial import receptor TOMM70 (PubMed:12526792). Apart from its chaperone activity, it also plays a role in the regulation of the transcription machinery. HSP90 and its co-chaperones modulate transcription at least at three different levels (PubMed:25973397). In the first place, they alter the steady-state levels of certain transcription factors in response to various physiological cues (PubMed:25973397). Second, they modulate the activity of certain epigenetic modifiers, such as histone deacetylases or DNA methyl transferases, and thereby respond to the change in the environment (PubMed:25973397). Third, they participate in the eviction of histones from the promoter region of certain genes and thereby turn on gene expression (PubMed:25973397). Binds bacterial lipopolysaccharide (LPS) and mediates LPS-induced inflammatory response, including TNF secretion by monocytes (PubMed:11276205). Antagonizes STUB1-mediated inhibition of TGF-beta signaling via inhibition of STUB1-mediated SMAD3 ubiquitination and degradation (PubMed:24613385). Mediates the association of TOMM70 with IRF3 or TBK1 in mitochondrial outer membrane which promotes host antiviral response (PubMed:20628368, PubMed:25609812)\n(Microbial infection) Seems to interfere with N.meningitidis NadA-mediated invasion of human cells. Decreasing HSP90 levels increases adhesion and entry of E.coli expressing NadA into human Chang cells; increasing its levels leads to decreased adhesion and invasion","subunit":"Homodimer (PubMed:18400751, PubMed:29127155, PubMed:7588731, PubMed:8289821). Identified in NR3C1/GCR steroid receptor-chaperone complexes formed at least by NR3C1, HSP90AA1 and a variety of proteins containing TPR repeats such as FKBP4, FKBP5, PPID, PPP5C or STIP1 (PubMed:15383005, PubMed:9195923). Forms a complex containing HSP90AA1, TSC1 and TSC2; TSC1 is required to recruit TCS2 to the complex (PubMed:29127155). The closed form interacts (via the middle domain and TPR repeat-binding motif) with co-chaperone TSC1 (via C-terminus) (PubMed:29127155). Interacts with TOM34 (PubMed:9660753). Interacts with TERT; the interaction, together with PTGES3, is required for correct assembly and stabilization of the TERT holoenzyme complex (PubMed:11274138, PubMed:9817749). Interacts with CHORDC1 and DNAJC7 (PubMed:12853476, PubMed:19875381). Interacts with STUB1 and UBE2N; may couple the chaperone and ubiquitination systems (PubMed:16307917, PubMed:27353360). Interacts (via TPR repeat-binding motif) with PPP5C (via TPR repeats); the interaction is direct and activates PPP5C phosphatase activity (PubMed:15383005, PubMed:15577939, PubMed:16531226, PubMed:27353360). Following LPS binding, may form a complex with CXCR4, GDF5 and HSPA8 (PubMed:11276205). Interacts with KSR1 (PubMed:10409742). Interacts with co-chaperone CDC37 (via C-terminus); the interaction inhibits HSP90AA1 ATPase activity (PubMed:23569206, PubMed:27353360). May interact with NWD1 (PubMed:24681825). Interacts with FNIP1 and FNIP2; the interaction inhibits HSP90AA1 ATPase activity (PubMed:17028174, PubMed:27353360). Interacts with co-chaperone AHSA1 (phosphorylated on 'Tyr-223'); the interaction activates HSP90AA1 ATPase activity and results in the dissociation of TSC1 from HSP90AA1 (PubMed:12604615, PubMed:27353360, PubMed:29127155). Interacts with FLCN in the presence of FNIP1 (PubMed:27353360). Interacts with HSP70, STIP1 and PTGES3 (PubMed:27353360). Interacts with SMYD3; this interaction enhances SMYD3 histone-lysine N-methyltransferase (PubMed:15235609, PubMed:25738358). Interacts with SGTA (via TPR repeats) (PubMed:15708368). Interacts with TTC1 (via TPR repeats) (PubMed:15708368). Interacts with HSF1 in an ATP-dependent manner (PubMed:11583998, PubMed:26517842). Interacts with MET; the interaction suppresses MET kinase activity (PubMed:26517842). Interacts with ERBB2 in an ATP-dependent manner; the interaction suppresses ERBB2 kinase activity (PubMed:26517842). Interacts with HIF1A, KEAP1 and RHOBTB2 (PubMed:26517842). Interacts with HSF1; this interaction is decreased in a IER5-dependent manner, promoting HSF1 accumulation in the nucleus, homotrimerization and DNA-binding activities (PubMed:26754925). Interacts with STUB1 and SMAD3 (PubMed:24613385). Interacts with HSP90AB1; interaction is constitutive (PubMed:20353823). Interacts with HECTD1 (via N-terminus) (By similarity). Interacts with NR3C1 (via domain NR LBD) and NR1D1 (via domain NR LBD) (By similarity). Interacts with NLPR12 (PubMed:17947705, PubMed:30559449). Interacts with PDCL3 (By similarity). Interacts with TOMM70; the interaction is required for preprotein mitochondrial import (PubMed:12526792). Interacts with TOMM70, IRF3 and TBK1; the interactions are direct and mediate the association of TOMM70 with IRF3 and TBK1 (PubMed:20628368). Forms a complex with ASL, ASS1 and NOS2; the complex regulates cell-autonomous L-arginine synthesis and citrulline recycling while channeling extracellular L-arginine to nitric oxide synthesis pathway\n(Microbial infection) Interacts with herpes simplex virus 1 protein US11; this interaction inhibits TBK1-induced interferon production\n(Microbial infection) Interacts with N.meningitidis serogroup B adhesin A (nadA). Interaction is stabilized by ADP and 17-AAG (17-N-allylamino-17-demethoxygeldanamycin) and inhibited by ATP. Decreasing HSP90 levels increases adhesion and entry of bacterial into human Chang cells; increasing its levels leads to decreased adhseion and invasion","family":"Belongs to the heat shock protein 90 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11274138","11276205","12526792","15577939","15937123","20628368","22066472","24613385","25609812","25973397","26991466","27295069","27353360","29127155"],"location":"Nucleus；Cytoplasm；Melanosome；Cell membrane；Mitochondrion","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"HSP90伴侣；帮助激酶等客户蛋白成熟/稳定。","function_evidence":"含实验支持条目；ECO:0000269,ECO:0000303,ECO:0000305","categories":"泛素化/蛋白稳态；染色质/转录调控；细胞周期/分裂；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面"},"HSP90AB1":{"hgnc":"HGNC:5258","symbol":"HSP90AB1","accessions":["P08238"],"name":"Heat shock protein HSP 90-beta","length":"724","function":"Molecular chaperone that promotes the maturation, structural maintenance and proper regulation of specific target proteins involved for instance in cell cycle control and signal transduction. Undergoes a functional cycle linked to its ATPase activity. This cycle probably induces conformational changes in the client proteins, thereby causing their activation. Interacts dynamically with various co-chaperones that modulate its substrate recognition, ATPase cycle and chaperone function (PubMed:16478993, PubMed:19696785). Engages with a range of client protein classes via its interaction with various co-chaperone proteins or complexes, that act as adapters, simultaneously able to interact with the specific client and the central chaperone itself. Recruitment of ATP and co-chaperone followed by client protein forms a functional chaperone. After the completion of the chaperoning process, properly folded client protein and co-chaperone leave HSP90 in an ADP-bound partially open conformation and finally, ADP is released from HSP90 which acquires an open conformation for the next cycle (PubMed:26991466, PubMed:27295069). Apart from its chaperone activity, it also plays a role in the regulation of the transcription machinery. HSP90 and its co-chaperones modulate transcription at least at three different levels. They first alter the steady-state levels of certain transcription factors in response to various physiological cues. Second, they modulate the activity of certain epigenetic modifiers, such as histone deacetylases or DNA methyl transferases, and thereby respond to the change in the environment. Third, they participate in the eviction of histones from the promoter region of certain genes and thereby turn on gene expression (PubMed:25973397). Antagonizes STUB1-mediated inhibition of TGF-beta signaling via inhibition of STUB1-mediated SMAD3 ubiquitination and degradation (PubMed:24613385). Promotes cell differentiation by chaperoning BIRC2 and thereby protecting from auto-ubiquitination and degradation by the proteasomal machinery (PubMed:18239673). Main chaperone involved in the phosphorylation/activation of the STAT1 by chaperoning both JAK2 and PRKCE under heat shock and in turn, activates its own transcription (PubMed:20353823). Involved in the translocation into ERGIC (endoplasmic reticulum-Golgi intermediate compartment) of leaderless cargos (lacking the secretion signal sequence) such as the interleukin 1/IL-1; the translocation process is mediated by the cargo receptor TMED10 (PubMed:32272059)\n(Microbial infection) Binding to N.meningitidis NadA stimulates monocytes (PubMed:21949862). Seems to interfere with N.meningitidis NadA-mediated invasion of human cells (Probable)","subunit":"Monomer (PubMed:24880080). Homodimer (PubMed:18400751, PubMed:7588731). Forms a complex with CDK6 and CDC37 (PubMed:25486457, PubMed:9482106). Interacts with UNC45A; binding to UNC45A involves 2 UNC45A monomers per HSP90AB1 dimer (PubMed:16478993). Interacts with CHORDC1 (By similarity). Interacts with DNAJC7 (PubMed:18620420). Interacts with FKBP4 (PubMed:15159550). May interact with NWD1 (PubMed:24681825). Interacts with SGTA (PubMed:16580629). Interacts with HSF1 in an ATP-dependent manner. Interacts with MET; the interaction suppresses MET kinase activity. Interacts with ERBB2 in an ATP-dependent manner; the interaction suppresses ERBB2 kinase activity. Interacts with HIF1A, KEAP1 and RHOBTB2 (PubMed:26517842). Interacts with STUB1 and SMAD3 (PubMed:24613385). Interacts with XPO1 and AHSA1 (PubMed:22022502, PubMed:25486457). Interacts with BIRC2 (PubMed:25486457). Interacts with KCNQ4; promotes cell surface expression of KCNQ4 (PubMed:23431407). Interacts with BIRC2; prevents auto-ubiquitination and degradation of its client protein BIRC2 (PubMed:18239673). Interacts with NOS3 (PubMed:23585225). Interacts with AHR; interaction is inhibited by HSP90AB1 phosphorylation on Ser-226 and Ser-255 (PubMed:15581363). Interacts with STIP1 and CDC37; upon SMYD2-dependent methylation (PubMed:24880080). Interacts with JAK2 and PRKCE; promotes functional activation in a heat shock-dependent manner (PubMed:20353823). Interacts with HSP90AA1; interaction is constitutive (PubMed:20353823). HSP90AB1-CDC37 chaperone complex interacts with inactive MAPK7 (via N-terminal half) in resting cells; the interaction is MAP2K5-independent and prevents from ubiquitination and proteasomal degradation (PubMed:23428871). Interacts with CDC25A; prevents heat shock-mediated CDC25A degradation and contributes to cell cycle progression (PubMed:22843495). Interacts with TP53 (via DNA binding domain); suppresses TP53 aggregation and prevents from irreversible thermal inactivation (PubMed:15358771). Interacts with TGFB1 processed form (LAP); inhibits latent TGFB1 activation (PubMed:20599762). Interacts with TRIM8; prevents nucleus translocation of phosphorylated STAT3 and HSP90AB1 (By similarity). Interacts with NR3C1 (via domain NR LBD) and NR1D1 (via domain NR LBD) (By similarity). Interacts with PDCL3 (By similarity). Interacts with TTC4 (via TPR repeats) (PubMed:18320024). Interacts with IL1B; the interaction facilitates cargo translocation into the ERGIC (PubMed:32272059)\n(Microbial infection) Protein on the cell surface interacts with N.meningitidis serogroup B adhesin A (nadA)","family":"Belongs to the heat shock protein 90 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16478993","18239673","19696785","20353823","21949862","22066472","24613385","25973397","26991466","27295069","32272059"],"location":"Cytoplasm；Melanosome；Nucleus；Secreted；Cell membrane；Dynein axonemal particle；Cell surface","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"HSP90伴侣；ATP依赖客户蛋白成熟/稳态。","function_evidence":"含实验支持条目；ECO:0000269,ECO:0000303,ECO:0000305","categories":"泛素化/蛋白稳态；染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；膜运输/高尔基/内吞；黏附/受体/细胞表面；发育/分化"},"HSP90B1":{"hgnc":"HGNC:12028","symbol":"HSP90B1","accessions":["P14625"],"name":"Endoplasmin","length":"803","function":"ATP-dependent chaperone involved in the processing of proteins in the endoplasmic reticulum, regulating their transport (PubMed:23572575, PubMed:39509507). Together with MESD, acts as a modulator of the Wnt pathway by promoting the folding of LRP6, a coreceptor of the canonical Wnt pathway (PubMed:23572575, PubMed:39509507). When associated with CNPY3, required for proper folding of Toll-like receptors (PubMed:11584270). Promotes folding and trafficking of TLR4 to the cell surface (PubMed:11584270). May participate in the unfolding of cytosolic leaderless cargos (lacking the secretion signal sequence) such as the interleukin 1/IL-1 to facilitate their translocation into the ERGIC (endoplasmic reticulum-Golgi intermediate compartment) and secretion; the translocation process is mediated by the cargo receptor TMED10 (PubMed:32272059)","subunit":"Homodimer; disulfide-linked. Component of an EIF2 complex at least composed of CELF1/CUGBP1, CALR, CALR3, EIF2S1, EIF2S2, HSP90B1 and HSPA5 (By similarity). Part of a large chaperone multiprotein complex comprising DNAJB11, HSP90B1, HSPA5, HYOU, PDIA2, PDIA4, PDIA6, PPIB, SDF2L1, UGGT1 and very small amounts of ERP29, but not, or at very low levels, CALR nor CANX. Interacts with AIMP1; regulates its retention in the endoplasmic reticulum. Hyperglycosylated form interacts with OS9; promoting its degradation by the endoplasmic reticulum associated degradation (ERAD) (PubMed:18264092, PubMed:24899641). Interacts with CNPY3. This interaction is disrupted in the presence of ATP (By similarity). Interacts with TLR4 and TLR9, but not with TLR3 (PubMed:20865800). Interacts with MZB1 in a calcium-dependent manner (By similarity). Interacts with METTL23 (PubMed:23349634). Interacts with IL1B; the interaction facilitates cargo translocation into the ERGIC (PubMed:32272059). Interacts with EIF2AK3 (PubMed:11907036)","family":"Belongs to the heat shock protein 90 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11584270","23572575","32272059","39509507"],"location":"Endoplasmic reticulum lumen；Sarcoplasmic reticulum lumen；Melanosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"膜运输/高尔基/内吞；黏附/受体/细胞表面；注释原文：ATP-dependent chaperone involved in the processing of proteins in the endoplasmic reticulum, regulating their transport (PubMed:23572575, PubMed:39509507).","function_evidence":"含实验支持条目；ECO:0000269","categories":"膜运输/高尔基/内吞；黏附/受体/细胞表面"},"HSPA12A":{"hgnc":"HGNC:19022","symbol":"HSPA12A","accessions":["O43301"],"name":"Heat shock 70 kDa protein 12A","length":"675","function":"Adapter protein for SORL1, but not SORT1. Delays SORL1 internalization and affects SORL1 subcellular localization","subunit":"Interacts with SORL1 (via cytosolic C-terminus); this interaction affects SORL1 internalization and subcellular localization","family":"Belongs to the heat shock protein 70 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["30679749"],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"；注释原文：Adapter protein for SORL1, but not SORT1.","function_evidence":"含实验支持条目；ECO:0000269","categories":"未归类"},"HSPA12B":{"hgnc":"HGNC:16193","symbol":"HSPA12B","accessions":["Q96MM6"],"name":"Heat shock 70 kDa protein 12B","length":"686","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"Belongs to the heat shock protein 70 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"HSPA13":{"hgnc":"HGNC:11375","symbol":"HSPA13","accessions":["P48723"],"name":"Heat shock 70 kDa protein 13","length":"471","function":"Has peptide-independent ATPase activity","subunit":"Binds UBQLN2","family":"Belongs to the heat shock protein 70 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Microsome；Endoplasmic reticulum","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"；注释原文：Has peptide-independent ATPase activity","function_evidence":"数据库整理/推断；按原文限定；","categories":"未归类"},"HSPA14":{"hgnc":"HGNC:29526","symbol":"HSPA14","accessions":["Q0VDF9"],"name":"Heat shock 70 kDa protein 14","length":"509","function":"Component of the ribosome-associated complex (RAC), a complex involved in folding or maintaining nascent polypeptides in a folding-competent state. In the RAC complex, binds to the nascent polypeptide chain, while DNAJC2 stimulates its ATPase activity","subunit":"Component of ribosome-associated complex (RAC), a heterodimer composed of Hsp70/DnaK-type chaperone HSPA14 and Hsp40/DnaJ-type chaperone DNAJC2","family":"Belongs to the heat shock protein 70 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16002468"],"location":"Cytoplasm, cytosol","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"翻译/核糖体；注释原文：Component of the ribosome-associated complex (RAC), a complex involved in folding or maintaining nascent polypeptides in a folding-competent state.","function_evidence":"含实验支持条目；ECO:0000269","categories":"翻译/核糖体"},"HSPA1A":{"hgnc":"HGNC:5232","symbol":"HSPA1A","accessions":["P0DMV8"],"name":"Heat shock 70 kDa protein 1A","length":"641","function":"Molecular chaperone implicated in a wide variety of cellular processes, including protection of the proteome from stress, folding and transport of newly synthesized polypeptides, activation of proteolysis of misfolded proteins and the formation and dissociation of protein complexes. Plays a pivotal role in the protein quality control system, ensuring the correct folding of proteins, the re-folding of misfolded proteins and controlling the targeting of proteins for subsequent degradation. This is achieved through cycles of ATP binding, ATP hydrolysis and ADP release, mediated by co-chaperones. The co-chaperones have been shown to not only regulate different steps of the ATPase cycle, but they also have an individual specificity such that one co-chaperone may promote folding of a substrate while another may promote degradation. The affinity for polypeptides is regulated by its nucleotide bound state. In the ATP-bound form, it has a low affinity for substrate proteins. However, upon hydrolysis of the ATP to ADP, it undergoes a conformational change that increases its affinity for substrate proteins. It goes through repeated cycles of ATP hydrolysis and nucleotide exchange, which permits cycles of substrate binding and release. The co-chaperones are of three types: J-domain co-chaperones such as HSP40s (stimulate ATPase hydrolysis by HSP70), the nucleotide exchange factors (NEF) such as BAG1/2/3 (facilitate conversion of HSP70 from the ADP-bound to the ATP-bound state thereby promoting substrate release), and the TPR domain chaperones such as HOPX and STUB1 (PubMed:24012426, PubMed:24318877, PubMed:26865365). Maintains protein homeostasis during cellular stress through two opposing mechanisms: protein refolding and degradation. Its acetylation/deacetylation state determines whether it functions in protein refolding or protein degradation by controlling the competitive binding of co-chaperones HOPX and STUB1. During the early stress response, the acetylated form binds to HOPX which assists in chaperone-mediated protein refolding, thereafter, it is deacetylated and binds to ubiquitin ligase STUB1 that promotes ubiquitin-mediated protein degradation (PubMed:27708256). Regulates centrosome integrity during mitosis, and is required for the maintenance of a functional mitotic centrosome that supports the assembly of a bipolar mitotic spindle (PubMed:27137183). Enhances STUB1-mediated SMAD3 ubiquitination and degradation and facilitates STUB1-mediated inhibition of TGF-beta signaling (PubMed:24613385). Essential for STUB1-mediated ubiquitination and degradation of FOXP3 in regulatory T-cells (Treg) during inflammation (PubMed:23973223). Required as a co-chaperone for optimal STUB1/CHIP ubiquitination of NFATC3 (By similarity). Negatively regulates heat shock-induced HSF1 transcriptional activity during the attenuation and recovery phase period of the heat shock response (PubMed:9499401). Involved in the clearance of misfolded PRDM1/Blimp-1 proteins. Sequesters them in the cytoplasm and promotes their association with SYNV1/HRD1, leading to proteasomal degradation (PubMed:28842558)\n(Microbial infection) In case of rotavirus A infection, serves as a post-attachment receptor for the virus to facilitate entry into the cell","subunit":"Component of the CatSper complex. Identified in a IGF2BP1-dependent mRNP granule complex containing untranslated mRNAs (PubMed:17289661). Interacts with CHCHD3, DNAJC7, IRAK1BP1, PPP5C and TSC2 (PubMed:12853476, PubMed:15383005, PubMed:15963462, PubMed:17233114, PubMed:18620420, PubMed:21081504). Interacts with TERT; the interaction occurs in the absence of the RNA component, TERC, and dissociates once the TERT complex has formed (PubMed:11274138). Interacts with TRIM5 (via B30.2/SPRY domain) (PubMed:20053985). Interacts with METTL21A (PubMed:23921388). Interacts with DNAAF2 (By similarity). Interacts with PRKN (PubMed:24270810). Interacts with FOXP3 (PubMed:23973223). Interacts with NOD2; the interaction enhances NOD2 stability (PubMed:24790089). Interacts with DNAJC9 (via J domain) (PubMed:17182002). Interacts with ATF5; the interaction protects ATF5 from degradation via proteasome-dependent and caspase-dependent processes (PubMed:22528486). Interacts with RNF207 (via the C-terminus); this interaction additively increases KCNH2 expression (PubMed:25281747). Interacts with HSF1 (via transactivation domain); this interaction results in the inhibition of heat shock- and HSF1-induced transcriptional activity during the attenuation and recovery phase period of the heat shock response (PubMed:7935376, PubMed:9499401). Interacts with NAA10, HSP40, HSP90 and HDAC4. Interacts (via C-terminus) with STUB1 (via TPR repeats) (By similarity). The acetylated form and the non-acetylated form interact with HOPX and STUB1 respectively (PubMed:27708256). Interacts with NEDD1 (PubMed:27137183). Interacts (via NBD) with BAG1, BAG2, BAG3 and HSPH1/HSP105 (PubMed:24318877). Interacts with SMAD3 (PubMed:24613385). Interacts with DNAJC8 (PubMed:27133716). Interacts with NLRP12 (PubMed:17947705). Interacts with PGLYRP (By similarity). Forms a ternary complex with BAG3 and HSPB8 (PubMed:27884606). Interacts with TTC1 and HSP40/DNAJB1; these interactions prevent the negative role of HSPBP1 on HSP70 folding (PubMed:14503850)","family":"Belongs to the heat shock protein 70 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16537599","22528486","23973223","24012426","24318877","24613385","26865365","27137183","27708256","28842558","9499401"],"location":"Cytoplasm；Nucleus；Cytoplasm, cytoskeleton, microtubule organizing center, centrosome；Secreted","shared_sequence_gene_count":"2","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；细胞周期/分裂；细胞骨架/纤毛；免疫/炎症/细胞死亡；黏附/受体/细胞表面；注释原文：Molecular chaperone implicated in a wide variety of cellular processes, including protection of the proteome from stress, folding and transport of newly synthesized polypeptides, activation of proteolysis of misfolded proteins and the formation and dissociation of protein complexes.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269,ECO:0000303","categories":"泛素化/蛋白稳态；染色质/转录调控；细胞周期/分裂；细胞骨架/纤毛；免疫/炎症/细胞死亡；黏附/受体/细胞表面"},"HSPA1B":{"hgnc":"HGNC:5233","symbol":"HSPA1B","accessions":["P0DMV9"],"name":"Heat shock 70 kDa protein 1B","length":"641","function":"Molecular chaperone implicated in a wide variety of cellular processes, including protection of the proteome from stress, folding and transport of newly synthesized polypeptides, activation of proteolysis of misfolded proteins and the formation and dissociation of protein complexes. Plays a pivotal role in the protein quality control system, ensuring the correct folding of proteins, the re-folding of misfolded proteins and controlling the targeting of proteins for subsequent degradation. This is achieved through cycles of ATP binding, ATP hydrolysis and ADP release, mediated by co-chaperones. The co-chaperones have been shown to not only regulate different steps of the ATPase cycle, but they also have an individual specificity such that one co-chaperone may promote folding of a substrate while another may promote degradation. The affinity for polypeptides is regulated by its nucleotide bound state. In the ATP-bound form, it has a low affinity for substrate proteins. However, upon hydrolysis of the ATP to ADP, it undergoes a conformational change that increases its affinity for substrate proteins. It goes through repeated cycles of ATP hydrolysis and nucleotide exchange, which permits cycles of substrate binding and release. The co-chaperones are of three types: J-domain co-chaperones such as HSP40s (stimulate ATPase hydrolysis by HSP70), the nucleotide exchange factors (NEF) such as BAG1/2/3 (facilitate conversion of HSP70 from the ADP-bound to the ATP-bound state thereby promoting substrate release), and the TPR domain chaperones such as HOPX and STUB1 (PubMed:24012426, PubMed:24318877, PubMed:26865365). Maintains protein homeostasis during cellular stress through two opposing mechanisms: protein refolding and degradation. Its acetylation/deacetylation state determines whether it functions in protein refolding or protein degradation by controlling the competitive binding of co-chaperones HOPX and STUB1. During the early stress response, the acetylated form binds to HOPX which assists in chaperone-mediated protein refolding, thereafter, it is deacetylated and binds to ubiquitin ligase STUB1 that promotes ubiquitin-mediated protein degradation (PubMed:27708256). Regulates centrosome integrity during mitosis, and is required for the maintenance of a functional mitotic centrosome that supports the assembly of a bipolar mitotic spindle (PubMed:27137183). Enhances STUB1-mediated SMAD3 ubiquitination and degradation and facilitates STUB1-mediated inhibition of TGF-beta signaling (PubMed:24613385). Essential for STUB1-mediated ubiquitination and degradation of FOXP3 in regulatory T-cells (Treg) during inflammation (PubMed:23973223)\n(Microbial infection) In case of rotavirus A infection, serves as a post-attachment receptor for the virus to facilitate entry into the cell","subunit":"May be an auxiliary component of the CatSper complex. Identified in a IGF2BP1-dependent mRNP granule complex containing untranslated mRNAs (PubMed:17289661). Interacts with CHCHD3, DNAJC7, IRAK1BP1, PPP5C and TSC2 (PubMed:12853476, PubMed:15383005, PubMed:15963462, PubMed:17233114, PubMed:18620420, PubMed:21081504). Interacts with TERT; the interaction occurs in the absence of the RNA component, TERC, and dissociates once the TERT complex has formed (PubMed:11274138). Interacts with TRIM5 (via B30.2/SPRY domain) (PubMed:20053985). Interacts with METTL21A (PubMed:23921388). Interacts with PRKN (PubMed:24270810). Interacts with FOXP3 (PubMed:23973223). Interacts with NOD2; the interaction enhances NOD2 stability (PubMed:24790089). Interacts with DNAJC9 (via J domain) (PubMed:17182002, PubMed:33857403). Interacts with ATF5; the interaction protects ATF5 from degradation via proteasome-dependent and caspase-dependent processes (PubMed:22528486). Interacts with NAA10, HSP40, HSP90 and HDAC4. The acetylated form and the non-acetylated form interact with HOPX and STUB1 respectively (PubMed:27708256). Interacts with NEDD1 (PubMed:27137183). Interacts (via NBD) with BAG1, BAG2, BAG3 and HSPH1/HSP105 (PubMed:24318877). Interacts with SMAD3 (PubMed:24613385). Interacts with DNAJC8 (PubMed:27133716)","family":"Belongs to the heat shock protein 70 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16537599","22528486","23973223","24012426","24318877","24613385","26865365","27137183","27708256"],"location":"Cytoplasm；Cytoplasm, cytoskeleton, microtubule organizing center, centrosome","shared_sequence_gene_count":"2","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；细胞周期/分裂；细胞骨架/纤毛；免疫/炎症/细胞死亡；黏附/受体/细胞表面；注释原文：Molecular chaperone implicated in a wide variety of cellular processes, including protection of the proteome from stress, folding and transport of newly synthesized polypeptides, activation of proteolysis of misfolded proteins and the formation and dissociation of protein complexes.","function_evidence":"含实验支持条目；ECO:0000269,ECO:0000303","categories":"泛素化/蛋白稳态；细胞周期/分裂；细胞骨架/纤毛；免疫/炎症/细胞死亡；黏附/受体/细胞表面"},"HSPA1L":{"hgnc":"HGNC:5234","symbol":"HSPA1L","accessions":["P34931"],"name":"Heat shock 70 kDa protein 1-like","length":"641","function":"Molecular chaperone implicated in a wide variety of cellular processes, including protection of the proteome from stress, folding and transport of newly synthesized polypeptides, activation of proteolysis of misfolded proteins and the formation and dissociation of protein complexes. Plays a pivotal role in the protein quality control system, ensuring the correct folding of proteins, the re-folding of misfolded proteins and controlling the targeting of proteins for subsequent degradation. This is achieved through cycles of ATP binding, ATP hydrolysis and ADP release, mediated by co-chaperones. The affinity for polypeptides is regulated by its nucleotide bound state. In the ATP-bound form, it has a low affinity for substrate proteins. However, upon hydrolysis of the ATP to ADP, it undergoes a conformational change that increases its affinity for substrate proteins. It goes through repeated cycles of ATP hydrolysis and nucleotide exchange, which permits cycles of substrate binding and release (PubMed:26865365). Positive regulator of PRKN translocation to damaged mitochondria (PubMed:24270810)","subunit":"Interacts with PRKN","family":"Belongs to the heat shock protein 70 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["24270810","26865365"],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；线粒体/代谢；注释原文：Molecular chaperone implicated in a wide variety of cellular processes, including protection of the proteome from stress, folding and transport of newly synthesized polypeptides, activation of proteolysis of misfolded proteins and the formation and dissociation of protein complexes.","function_evidence":"含实验支持条目；ECO:0000269,ECO:0000303","categories":"泛素化/蛋白稳态；线粒体/代谢"},"HSPA2":{"hgnc":"HGNC:5235","symbol":"HSPA2","accessions":["P54652"],"name":"Heat shock-related 70 kDa protein 2","length":"639","function":"Molecular chaperone implicated in a wide variety of cellular processes, including protection of the proteome from stress, folding and transport of newly synthesized polypeptides, activation of proteolysis of misfolded proteins and the formation and dissociation of protein complexes. Plays a pivotal role in the protein quality control system, ensuring the correct folding of proteins, the re-folding of misfolded proteins and controlling the targeting of proteins for subsequent degradation. This is achieved through cycles of ATP binding, ATP hydrolysis and ADP release, mediated by co-chaperones. The affinity for polypeptides is regulated by its nucleotide bound state. In the ATP-bound form, it has a low affinity for substrate proteins. However, upon hydrolysis of the ATP to ADP, it undergoes a conformational change that increases its affinity for substrate proteins. It goes through repeated cycles of ATP hydrolysis and nucleotide exchange, which permits cycles of substrate binding and release (PubMed:26865365). Plays a role in spermatogenesis. In association with SHCBP1L may participate in the maintenance of spindle integrity during meiosis in male germ cells (By similarity)","subunit":"Interacts with FKBP6 (PubMed:18529014). Interacts with ZNF541. Component of the CatSper complex. Interacts with RABL2/RABL2A; binds preferentially to GTP-bound RABL2. Interacts with SHCBP1L; this interaction may promote the recruitment of HSPA2 to the spindle (By similarity). Interacts with FAM170A (By similarity)","family":"Belongs to the heat shock protein 70 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["26865365"],"location":"Cytoplasm, cytoskeleton, spindle","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；细胞周期/分裂；发育/分化；注释原文：Molecular chaperone implicated in a wide variety of cellular processes, including protection of the proteome from stress, folding and transport of newly synthesized polypeptides, activation of proteolysis of misfolded proteins and the formation and dissociation of protein complexes.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250,ECO:0000303","categories":"泛素化/蛋白稳态；细胞周期/分裂；发育/分化"},"HSPA6":{"hgnc":"HGNC:5239","symbol":"HSPA6","accessions":["P17066"],"name":"Heat shock 70 kDa protein 6","length":"643","function":"Molecular chaperone implicated in a wide variety of cellular processes, including protection of the proteome from stress, folding and transport of newly synthesized polypeptides, activation of proteolysis of misfolded proteins and the formation and dissociation of protein complexes. Plays a pivotal role in the protein quality control system, ensuring the correct folding of proteins, the re-folding of misfolded proteins and controlling the targeting of proteins for subsequent degradation. This is achieved through cycles of ATP binding, ATP hydrolysis and ADP release, mediated by co-chaperones. The affinity for polypeptides is regulated by its nucleotide bound state. In the ATP-bound form, it has a low affinity for substrate proteins. However, upon hydrolysis of the ATP to ADP, it undergoes a conformational change that increases its affinity for substrate proteins. It goes through repeated cycles of ATP hydrolysis and nucleotide exchange, which permits cycles of substrate binding and release (PubMed:26865365)","subunit":"无可用SUBUNIT段","family":"Belongs to the heat shock protein 70 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["26865365"],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；注释原文：Molecular chaperone implicated in a wide variety of cellular processes, including protection of the proteome from stress, folding and transport of newly synthesized polypeptides, activation of proteolysis of misfolded proteins and the formation and dissociation of protein complexes.","function_evidence":"数据库整理/推断；按原文限定；ECO:0000303","categories":"泛素化/蛋白稳态"},"HSPA8":{"hgnc":"HGNC:5241","symbol":"HSPA8","accessions":["P11142"],"name":"Heat shock cognate 71 kDa protein","length":"646","function":"Molecular chaperone implicated in a wide variety of cellular processes, including protection of the proteome from stress, folding and transport of newly synthesized polypeptides, chaperone-mediated autophagy, activation of proteolysis of misfolded proteins, formation and dissociation of protein complexes, and antigen presentation. Plays a pivotal role in the protein quality control system, ensuring the correct folding of proteins, the re-folding of misfolded proteins and controlling the targeting of proteins for subsequent degradation (PubMed:21148293, PubMed:21150129, PubMed:23018488, PubMed:24732912, PubMed:27916661, PubMed:2799391, PubMed:36586411). This is achieved through cycles of ATP binding, ATP hydrolysis and ADP release, mediated by co-chaperones (PubMed:12526792, PubMed:21148293, PubMed:21150129, PubMed:23018488, PubMed:24732912, PubMed:27916661). The co-chaperones have been shown to not only regulate different steps of the ATPase cycle of HSP70, but they also have an individual specificity such that one co-chaperone may promote folding of a substrate while another may promote degradation (PubMed:12526792, PubMed:21148293, PubMed:21150129, PubMed:23018488, PubMed:24732912, PubMed:27916661). The affinity of HSP70 for polypeptides is regulated by its nucleotide bound state. In the ATP-bound form, it has a low affinity for substrate proteins. However, upon hydrolysis of the ATP to ADP, it undergoes a conformational change that increases its affinity for substrate proteins. HSP70 goes through repeated cycles of ATP hydrolysis and nucleotide exchange, which permits cycles of substrate binding and release. The HSP70-associated co-chaperones are of three types: J-domain co-chaperones HSP40s (stimulate ATPase hydrolysis by HSP70), the nucleotide exchange factors (NEF) such as BAG1/2/3 (facilitate conversion of HSP70 from the ADP-bound to the ATP-bound state thereby promoting substrate release), and the TPR domain chaperones such as HOPX and STUB1 (PubMed:24121476, PubMed:24318877, PubMed:26865365, PubMed:27474739). Plays a critical role in mitochondrial import, delivers preproteins to the mitochondrial import receptor TOMM70 (PubMed:12526792). Acts as a repressor of transcriptional activation. Inhibits the transcriptional coactivator activity of CITED1 on Smad-mediated transcription. Component of the PRP19-CDC5L complex that forms an integral part of the spliceosome and is required for activating pre-mRNA splicing. May have a scaffolding role in the spliceosome assembly as it contacts all other components of the core complex. Binds bacterial lipopolysaccharide (LPS) and mediates LPS-induced inflammatory response, including TNF secretion by monocytes (PubMed:10722728, PubMed:11276205). Substrate recognition component in chaperone-mediated autophagy (CMA), a selective protein degradation process that mediates degradation of proteins with a -KFERQ motif: HSPA8/HSC70 specifically recognizes and binds cytosolic proteins bearing a -KFERQ motif and promotes their recruitment to the surface of the lysosome where they bind to lysosomal protein LAMP2 (PubMed:11559757, PubMed:2799391, PubMed:36586411). KFERQ motif-containing proteins are eventually transported into the lysosomal lumen where they are degraded (PubMed:11559757, PubMed:2799391, PubMed:36586411). In conjunction with LAMP2, facilitates MHC class II presentation of cytoplasmic antigens by guiding antigens to the lysosomal membrane for interaction with LAMP2 which then elicits MHC class II presentation of peptides to the cell membrane (PubMed:15894275). Participates in the ER-associated degradation (ERAD) quality control pathway in conjunction with J domain-containing co-chaperones and the E3 ligase STUB1 (PubMed:23990462). It is recruited to clathrin-coated vesicles through its interaction with DNAJC6 leading to activation of HSPA8/HSC70 ATPase activity and therefore uncoating of clathrin-coated vesicles (By similarity)","subunit":"Component of the chaperone-assisted selective autophagy (CASA) complex consisting of BAG3, HSPA8/HSC70, HSPB8 and STUB1/CHIP (PubMed:20060297). Identified in a IGF2BP1-dependent mRNP granule complex containing untranslated mRNAs. Interacts with PACRG. Interacts with HSPH1/HSP105. Interacts with IRAK1BP1 and BAG1. Interacts with DNAJC7. Interacts with DNAJB12 (via J domain) (PubMed:21148293, PubMed:21150129, PubMed:24732912, PubMed:27916661). Interacts with DNAJB14 (via J domain) (PubMed:23018488, PubMed:24732912, PubMed:27916661). Interacts (via C-terminus) with the E3 ligase CHIP forming a 210 kDa complex of one CHIP and two HSPA8 molecules. Interacts with CITED1 (via N-terminus); the interaction suppresses the association of CITED1 to p300/CBP and Smad-mediated transcription transactivation. Component of the PRP19-CDC5L splicing complex composed of a core complex comprising a homotetramer of PRPF19, CDC5L, PLRG1 and BCAS2, and at least three less stably associated proteins CTNNBL1, CWC15 and HSPA8. Interacts with TRIM5. Part of a complex composed at least of ASH2L, EMSY, HCFC1, HSPA8, CCAR2, MATR3, MKI67, RBBP5, TUBB2A, WDR5 and ZNF335; this complex may have a histone H3-specific methyltransferase activity. Interacts with METTL21A. Following LPS binding, may form a complex with CXCR4, GDF5 and HSP90AA1. Interacts with PRKN. Interacts with FOXP3. Interacts with DNAJC9 (via J domain) (PubMed:17182002). Interacts with MLLT11 (PubMed:24880125). Interacts with RNF207 (PubMed:25281747). Interacts with DNAJC21 (PubMed:27346687). Interacts with DNAJB2 (PubMed:15936278). Interacts with TTC1 (via TPR repeats) (PubMed:15708368). Interacts with SGTA (via TPR repeats) (By similarity). Interacts with HSF1 (via transactivation domain) (PubMed:9499401). Interacts with HOPX, HSP40 and HSP90 (PubMed:27708256). Interacts with STUB1 (PubMed:27708256). Interacts with BAG2 (PubMed:24318877). Interacts with BAG3 (PubMed:24318877, PubMed:27474739). Interacts with DNAJC12 (PubMed:24122553). Interacts with ZMYND10 (PubMed:29601588). Interacts with HSPC138 (PubMed:25760597). Interacts with BCL2L1, GIMAP5 and MCL1; the interaction with BCL2L1 or MCL1 is impaired in the absence of GIMAP5 (By similarity). Interacts with NLPR12 (PubMed:17947705). Interacts with TTC4 (PubMed:18320024). Interacts with TOMM70; the interaction is required for preprotein mitochondrial import (PubMed:12526792). May interact with DNJC9; the interaction seems to be histone-dependent (PubMed:33857403). Interacts with BAG5 and JPH2; the interaction with JPH2 is increased in the presence of BAG5 (PubMed:35044787). Interacts with VGF-derived peptide TLQP-21 (PubMed:28934328). Interacts with molecular chaperone MIPEP155 (via N-terminal ATP-binding region); the interaction results in reduced ATPase activity of HSPA8, impaired interaction of HSPA8 with HSP90 and reduced lysosomal antigen trafficking (PubMed:32671205). Interacts with CDKN1B; the interaction may be associated with susceptibility to ubiquitination (PubMed:26775844). Interacts with HTN3 peptide Hst3; the interaction enhances HSPA8-CDKN1B complex formation (PubMed:26775844). Interacts with DNAJC6 (via J domain) in an ATP-dependent manner; this interaction stimulates the HSPA8's ATPase activity. Forms a complex composed of HSPA8, CLTC and DNAJC6 (By similarity). Interacts with HSPA8; this interaction modulates migratory and antigen-presenting capacities of dendritic cells (PubMed:17785435, PubMed:20060297)\n(Microbial infection) Interacts with SV40 VP1\n(Microbial infection) Interacts with human herpes virus 1 (HHV-1) transcriptional regulator ICP22; this interaction recruits HSPA8/HSP40 to discrete nuclear foci","family":"Belongs to the heat shock protein 70 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10722728","11276205","11559757","12526792","15894275","21148293","21150129","23018488","23990462","24121476","24318877","24732912","26865365","27474739","27916661","2799391","36586411"],"location":"Cytoplasm；Melanosome；Nucleus, nucleolus；Cell membrane；Lysosome membrane；Peripheral membrane protein；Cytoplasmic side","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"HSC70分子伴侣；ATP依赖折叠/蛋白质量控制。","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269,ECO:0000303","categories":"泛素化/蛋白稳态；RNA加工/剪接；染色质/转录调控；膜运输/高尔基/内吞；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面"},"HSPA9":{"hgnc":"HGNC:5244","symbol":"HSPA9","accessions":["P38646"],"name":"Stress-70 protein, mitochondrial","length":"679","function":"Mitochondrial chaperone that plays a key role in mitochondrial protein import, folding, and assembly. Plays an essential role in the protein quality control system, the correct folding of proteins, the re-folding of misfolded proteins, and the targeting of proteins for subsequent degradation. These processes are achieved through cycles of ATP binding, ATP hydrolysis, and ADP release, mediated by co-chaperones (PubMed:18632665, PubMed:25615450, PubMed:28848044, PubMed:30933555, PubMed:31177526). In mitochondria, it associates with the TIM (translocase of the inner membrane) protein complex to assist in the import and folding of mitochondrial proteins (By similarity). Plays an important role in mitochondrial iron-sulfur cluster (ISC) biogenesis, interacts with and stabilizes ISC cluster assembly proteins FXN, NFU1, NFS1 and ISCU (PubMed:26702583). Regulates erythropoiesis via stabilization of ISC assembly (PubMed:21123823, PubMed:26702583). Regulates mitochondrial calcium-dependent apoptosis by coupling two calcium channels, ITPR1 and VDAC1, at the mitochondria-associated endoplasmic reticulum (ER) membrane to facilitate calcium transport from the ER lumen to the mitochondria intermembrane space, providing calcium for the downstream calcium channel MCU, which releases it into the mitochondrial matrix (By similarity). Although primarily located in the mitochondria, it is also found in other cellular compartments. In the cytosol, it associates with proteins involved in signaling, apoptosis, or senescence. It may play a role in cell cycle regulation via its interaction with and promotion of degradation of TP53 (PubMed:24625977, PubMed:26634371). May play a role in the control of cell proliferation and cellular aging (By similarity). Protects against reactive oxygen species (ROS) (By similarity). Extracellular HSPA9 plays a cytoprotective role by preventing cell lysis following immune attack by the membrane attack complex by disrupting formation of the complex (PubMed:16091382)","subunit":"Interacts strongly with the intermediate form of FXN and weakly with its mature form (PubMed:17331979, PubMed:26702583). Interacts with HSCB (PubMed:20668094). Associates with the mitochondrial contact site and cristae organizing system (MICOS) complex, composed of at least MICOS10/MIC10, CHCHD3/MIC19, CHCHD6/MIC25, APOOL/MIC27, IMMT/MIC60, APOO/MIC23/MIC26 and QIL1/MIC13. This complex was also known under the names MINOS or MitOS complex. The MICOS complex associates with mitochondrial outer membrane proteins SAMM50, MTX1, MTX2 and DNAJC11, mitochondrial inner membrane protein TMEM11 and with HSPA9 (PubMed:22114354). Interacts with DNLZ, the interaction is required to prevent self-aggregation (PubMed:23462535, PubMed:18632665). Interacts with TESPA1 (PubMed:23501103). Interacts with PDPN (PubMed:23541579). Interacts with NFU1, NFS1 and ISCU (PubMed:26702583). Interacts with TP53; the interaction promotes TP53 degradation (PubMed:24625977). Interacts (via SBD domain) with UBXN2A; the interaction with UBXN2A inhibits HSPA9 interaction with and degradation of TP53, thereby promotes TP53 translocation to the nucleus (PubMed:24625977, PubMed:26634371). Interacts with ITPR1 AND VDAC1; this interaction couples ITPR1 to VDAC1 (By similarity). Interacts with the TIM23 mitochondrial inner membrane pre-sequence translocase complex (PubMed:10339406). Interacts with GRPEL1; GRPEL1 functions as a nucleotide exchange factor (NEF) for HSPA9 (PubMed:39737924)","family":"Belongs to the heat shock protein 70 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16091382","18632665","21123823","24625977","25615450","26634371","26702583","28848044","30933555","31177526"],"location":"Mitochondrion；Nucleus, nucleolus；Cytoplasm；Mitochondrion matrix","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；细胞周期/分裂；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；注释原文：Mitochondrial chaperone that plays a key role in mitochondrial protein import, folding, and assembly.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；细胞周期/分裂；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面"},"HSPB1":{"hgnc":"HGNC:5246","symbol":"HSPB1","accessions":["P04792"],"name":"Heat shock protein beta-1","length":"205","function":"Small heat shock protein which functions as a molecular chaperone probably maintaining denatured proteins in a folding-competent state (PubMed:10383393, PubMed:20178975). Plays a role in stress resistance and actin organization (PubMed:19166925). Through its molecular chaperone activity may regulate numerous biological processes including the phosphorylation and the axonal transport of neurofilament proteins (PubMed:23728742)","subunit":"Homooligomer (PubMed:10383393). Homodimer; becomes monomeric upon activation (PubMed:20178975). Heterooligomer; with HSPB6 (PubMed:23948568). Associates with alpha- and beta-tubulin (PubMed:10777697). Interacts with TGFB1I1 (By similarity). Interacts with CRYAB (PubMed:1560006). Interacts with HSPB8 (PubMed:11342557). Interacts with HSPBAP1 (PubMed:10751411)","family":"Belongs to the small heat shock protein (HSP20) family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10383393","19166925","20178975","23728742"],"location":"Cytoplasm；Nucleus；Cytoplasm, cytoskeleton, spindle","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；细胞骨架/纤毛；注释原文：Small heat shock protein which functions as a molecular chaperone probably maintaining denatured proteins in a folding-competent state (PubMed:10383393, PubMed:20178975).","function_evidence":"含实验支持条目；ECO:0000269","categories":"激酶/磷酸化信号；细胞骨架/纤毛"},"HSPB2":{"hgnc":"HGNC:5247","symbol":"HSPB2","accessions":["Q16082"],"name":"Heat shock protein beta-2","length":"182","function":"May regulate the kinase DMPK","subunit":"Interacts with DMPK; may enhance its kinase activity","family":"Belongs to the small heat shock protein (HSP20) family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["9490724"],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；注释原文：May regulate the kinase DMPK","function_evidence":"含实验支持条目；ECO:0000269","categories":"激酶/磷酸化信号"},"HSPB7":{"hgnc":"HGNC:5249","symbol":"HSPB7","accessions":["Q9UBY9"],"name":"Heat shock protein beta-7","length":"170","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"Interacts with C-terminal domain of actin-binding protein 280","family":"Belongs to the small heat shock protein (HSP20) family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Cytoplasm；Nucleus；Nucleus, Cajal body","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"HSPB8":{"hgnc":"HGNC:30171","symbol":"HSPB8","accessions":["Q9UJY1"],"name":"Heat shock protein beta-8","length":"196","function":"Involved in the chaperone-assisted selective autophagy (CASA), a crucial process for protein quality control, particularly in mechanical strained cells and tissues such as muscle. Displays temperature-dependent chaperone activity","subunit":"Monomer. Forms a ternary complex with BAG3 and HSPA1A (PubMed:27884606). Component of the chaperone-assisted selective autophagy (CASA) complex consisting of BAG3, HSPA8/HSC70, HSPB8 and STUB1/CHIP (PubMed:20060297). Interacts with HSPB1 (PubMed:11342557). Interacts with DNAJB6 (PubMed:22366786). Interacts with BAG3 (PubMed:28144995)","family":"Belongs to the small heat shock protein (HSP20) family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；注释原文：Involved in the chaperone-assisted selective autophagy (CASA), a crucial process for protein quality control, particularly in mechanical strained cells and tissues such as muscle.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"泛素化/蛋白稳态"},"HSPH1":{"hgnc":"HGNC:16969","symbol":"HSPH1","accessions":["Q92598"],"name":"Heat shock protein 105 kDa","length":"858","function":"Acts as a nucleotide-exchange factor (NEF) for chaperone proteins HSPA1A and HSPA1B, promoting the release of ADP from HSPA1A/B thereby triggering client/substrate protein release (PubMed:24318877). Prevents the aggregation of denatured proteins in cells under severe stress, on which the ATP levels decrease markedly. Inhibits HSPA8/HSC70 ATPase and chaperone activities (By similarity)","subunit":"Interacts with HSPA8/HSC70 (By similarity). Interacts with HSPA1A (via NBD) and HSPA1B (via NBD) (PubMed:24318877)","family":"Belongs to the heat shock protein 70 family","domains":[],"function_pmids":["24318877"],"location":"Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Acts as a nucleotide-exchange factor (NEF) for chaperone proteins HSPA1A and HSPA1B, promoting the release of ADP from HSPA1A/B thereby triggering client/substrate protein release (PubMed:24318877). Prevents the aggregation of denatured proteins in cells under severe stress, on which the ATP levels decrease markedly. Inhibits HSPA8/HSC70 ATPase and chaperone activities (By similarity)"},"HTATSF1":{"hgnc":"HGNC:5276","symbol":"HTATSF1","accessions":["O43719"],"name":"17S U2 SnRNP complex component HTATSF1","length":"755","function":"Component of the 17S U2 SnRNP complex of the spliceosome, a large ribonucleoprotein complex that removes introns from transcribed pre-mRNAs (PubMed:30567737, PubMed:32494006, PubMed:34822310). The 17S U2 SnRNP complex (1) directly participates in early spliceosome assembly and (2) mediates recognition of the intron branch site during pre-mRNA splicing by promoting the selection of the pre-mRNA branch-site adenosine, the nucleophile for the first step of splicing (PubMed:30567737, PubMed:32494006, PubMed:34822310). Within the 17S U2 SnRNP complex, HTATSF1 is required to stabilize the branchpoint-interacting stem loop (PubMed:34822310). HTATSF1 is displaced from the 17S U2 SnRNP complex before the stable addition of the 17S U2 SnRNP complex to the spliceosome, destabilizing the branchpoint-interacting stem loop and allowing to probe intron branch site sequences (PubMed:32494006, PubMed:34822310). Also acts as a regulator of transcriptional elongation, possibly by mediating the reciprocal stimulatory effect of splicing on transcriptional elongation (PubMed:10454543, PubMed:10913173, PubMed:11780068). Involved in double-strand break (DSB) repair via homologous recombination in S-phase by promoting the recruitment of TOPBP1 to DNA damage sites (PubMed:35597237). Mechanistically, HTATSF1 is (1) recruited to DNA damage sites in S-phase via interaction with poly-ADP-ribosylated RPA1 and (2) phosphorylated by CK2, promoting recruitment of TOPBP1, thereby facilitating RAD51 nucleofilaments formation and RPA displacement, followed by homologous recombination (PubMed:35597237)\n(Microbial infection) In case of infection by HIV-1, it is up-regulated by the HIV-1 proteins NEF and gp120, acts as a cofactor required for the Tat-enhanced transcription of the virus","subunit":"Component of the 17S U2 SnRNP complex, a ribonucleoprotein complex that contains small nuclear RNA (snRNA) U2 and a number of specific proteins (PubMed:11780068, PubMed:30567737, PubMed:32494006, PubMed:34822310, PubMed:9710584). Within the 17S U2 SnRNP complex, interacts (via UHM region) directly with SF3B1 (PubMed:30567737). Component of a complex which is at least composed of HTATSF1/Tat-SF1, the P-TEFb complex components CDK9 and CCNT1, RNA polymerase II, SUPT5H, and NCL/nucleolin (PubMed:10393184, PubMed:10454543, PubMed:10913173, PubMed:11780068, PubMed:9649438). Interacts with GTF2F2/RAP30 and POLR2A (PubMed:10454543). Interacts with TCERG1/CA150 (PubMed:15485897). Interacts with (poly-ADP-ribosylated) RPA1; promoting HTATSF1 recruitment to DNA damage sites (PubMed:35597237). Interacts (when phosphorylated) with TOPBP1; promoting recruitment of TOPBP1 to DNA damage sites during S-phase (PubMed:35597237)","family":"Belongs to the HTATSF1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10393184","10454543","10913173","11420046","11780068","15905670","30567737","32494006","34822310","35597237","8849451","9765201"],"location":"Nucleus；Chromosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；DNA修复/复制；激酶/磷酸化信号；注释原文：Component of the 17S U2 SnRNP complex of the spliceosome, a large ribonucleoprotein complex that removes introns from transcribed pre-mRNAs (PubMed:30567737, PubMed:32494006, PubMed:34822310).","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；染色质/转录调控；DNA修复/复制；激酶/磷酸化信号"}};
